INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9lSFOt9wtL7', 1, '{"title":"金匮要略1  脏腑经络先后病","description":"<p>1、问曰：上工治未病，何也？师曰：夫治未病者，见肝之病，知肝传脾，当先实脾。四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，$a{俞桥本，赵开美本，更有心火气盛四字。}则伤肺；肺被伤，则金气不行；金气不行，则肝气盛。$a{俞本有故实脾三字，}则肝自愈。此治肝补脾之要妙也。肝虚则用此法，实则不在用之。经曰：虚虚实实，补不足，损有余。是其义也。余脏准此。</p><p>2、夫人秉五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和，客气邪风，中人多死。千般疢难，不越三条：一者，经络受邪，入脏腑，为内所因也；二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也；三者，房室、金刃、虫兽所伤，以此详之，病由都尽。若人能养慎，不令邪风干忤经络，适中经络，未流传脏腑，即医治之。四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。</p><p>3、问曰：病人有气色见于面部，愿闻其说。师曰：鼻头色青，腹中痛，苦冷者死。$a{一云腹中冷，苦痛者死。}鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤，非时者死。其目正圆者，痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。</p><p>4、师曰：病人语声寂然，喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病$a{一作痛}。</p><p>5、师曰：息摇肩者，心中坚；息引胸中上气者，咳；息张口短气者，肺痿唾沫。</p><p>6、师曰：吸而微数，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促；在下焦者，其吸远，此皆难治。呼吸动摇振振者，不治。</p><p>7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反色白，非其时色脉，皆当病。</p><p>8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起。少阳之时，阳始生，天得温和。以未得甲子，天因温和，此为未至而至也；以得甲子而天未温和，$a{此}为至而不至也；以得甲子而天大寒不解，此为至而不去也；以得甲子而天温如盛夏五六月时，此为至而太过也。</p><p>9、师曰：病人脉浮者在前，其病在表；浮者在后，其病在里。腰痛背强不能行，必短气而极也。</p><p>10、问曰：经云：厥阳独行，何谓也？师曰：此为有阳无阴，故称厥阳。</p><p>11、问曰：寸脉沉大而滑，沉则为实，滑则为气。实气相抟，血气入脏即死，入腑即愈，此为卒厥。何谓也？师曰：唇口青，身冷，为入脏即死；如身和，汗自出，为入腑即愈。</p><p>12、问曰：脉脱入脏即死，入腑即愈，何谓也？师曰：非为一病，百病皆然。譬如浸淫疮，从口起流向四肢者，可治；从四肢流来入口者，不可治；病在外者，可治；入里者，即死。</p><p>13、问曰：阳病十八，何谓也？师曰：头痛，项、腰、脊、臂、脚掣痛。阴病十八，何谓也？师曰：咳，上气，喘，哕，咽，肠鸣，胀满，心痛，拘急。五脏病各有十八，合为九十病。人又有六微，微有十八病，合为一百八病。五劳七伤六极，妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里。穀饪之邪，从口入者，宿食也。五邪中人，各有法度：风中于前，寒中于暮，湿伤于下，雾伤于上，风令脉浮，寒令脉急，雾伤皮腠，湿流关节，食伤脾胃，极寒伤经，极热伤络。</p><p>14、问曰：病有急当救里、救表者，何谓也？师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身体疼痛，清便自调者，急当救表也。</p><p>15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。</p><p>16、师曰：五脏病各有所得者愈，五脏病各有所恶，各随其所不喜者为病。病者素不应食，而反暴思之，必发热也。</p><p>17、夫诸病在脏欲攻之，当随其所得而攻之，如渴者，与$f{猪苓汤}，余皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":0,"no":1}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、问曰：上工治未病，何也？师曰：夫治未病者，见肝之病，知肝传脾，当先实脾。四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，$a{俞桥本，赵开美本，更有心火气盛四字。}则伤肺；肺被伤，则金气不行；金气不行，则肝气盛。$a{俞本有故实脾三字，}则肝自愈。此治肝补脾之要妙也。肝虚则用此法，实则不在用之。经曰：虚虚实实，补不足，损有余。是其义也。余脏准此。 2、夫人秉五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和，客气邪风，中人多死。千般疢难，不越三条：一者，经络受邪，入脏腑，为内所因也；二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也；三者，房室、金刃、虫兽所伤，以此详之，病由都尽。若人能养慎，不令邪风干忤经络，适中经络，未流传脏腑，即医治之。四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。 3、问曰：病人有气色见于面部，愿闻其说。师曰：鼻头色青，腹中痛，苦冷者死。$a{一云腹中冷，苦痛者死。}鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤，非时者死。其目正圆者，痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。 4、师曰：病人语声寂然，喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病$a{一作痛}。 5、师曰：息摇肩者，心中坚；息引胸中上气者，咳；息张口短气者，肺痿唾沫。 6、师曰：吸而微数，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促；在下焦者，其吸远，此皆难治。呼吸动摇振振者，不治。 7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反色白，非其时色脉，皆当病。 8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起。少阳之时，阳始生，天得温和。以未得甲子，天因温和，此为未至而至也；以得甲子而天未温和，$a{此}为至而不至也；以得甲子而天大寒不解，此为至而不去也；以得甲子而天温如盛夏五六月时，此为至而太过也。 9、师曰：病人脉浮者在前，其病在表；浮者在后，其病在里。腰痛背强不能行，必短气而极也。 10、问曰：经云：厥阳独行，何谓也？师曰：此为有阳无阴，故称厥阳。 11、问曰：寸脉沉大而滑，沉则为实，滑则为气。实气相抟，血气入脏即死，入腑即愈，此为卒厥。何谓也？师曰：唇口青，身冷，为入脏即死；如身和，汗自出，为入腑即愈。 12、问曰：脉脱入脏即死，入腑即愈，何谓也？师曰：非为一病，百病皆然。譬如浸淫疮，从口起流向四肢者，可治；从四肢流来入口者，不可治；病在外者，可治；入里者，即死。 13、问曰：阳病十八，何谓也？师曰：头痛，项、腰、脊、臂、脚掣痛。阴病十八，何谓也？师曰：咳，上气，喘，哕，咽，肠鸣，胀满，心痛，拘急。五脏病各有十八，合为九十病。人又有六微，微有十八病，合为一百八病。五劳七伤六极，妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里。穀饪之邪，从口入者，宿食也。五邪中人，各有法度：风中于前，寒中于暮，湿伤于下，雾伤于上，风令脉浮，寒令脉急，雾伤皮腠，湿流关节，食伤脾胃，极寒伤经，极热伤络。 14、问曰：病有急当救里、救表者，何谓也？师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身体疼痛，清便自调者，急当救表也。 15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。 16、师曰：五脏病各有所得者愈，五脏病各有所恶，各随其所不喜者为病。病者素不应食，而反暴思之，必发热也。 17、夫诸病在脏欲攻之，当随其所得而攻之，如渴者，与$f{猪苓汤}，余皆仿此。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0lHavJPW2wc', 1, '{"title":"金匮要略2  痉湿暍","description":"<p>1、太阳病，发热无汗，反恶寒者，名曰刚痉。</p><p>2、太阳病，发热汗出而不恶寒，名曰柔痉。</p><p>3、太阳病，发热，脉沉而细者，名曰痉，为难治。</p><p>4、太阳病，发汗太多，因致痉。</p><p>5、夫风病，下之则痉，复发汗，必拘急。</p><p>6、疮家虽身疼痛，不可发汗，汗出则痉。</p><p>7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗者，寒湿相得，其表益虚，即恶寒甚。发其汗已，其脉如蛇。</p><p>8、暴腹胀大者，为欲解，脉如故，反伏弦者，痉。</p><p>9、夫痉脉，按之紧如弦，直上下行。$a{一作筑筑而弦。《脉经》云：痉家其脉伏坚，直上下。}</p><p>10、痉病有灸疮，难治。</p><p>11、太阳病，其证备，身体强几几，然脉反沉迟，此为痉，$f{栝楼桂枝汤}主之。</p><p>12、太阳病，无汗而小便反少，气上冲胸，口噤不得语，欲作刚痉，$f{葛根汤}主之。</p><p>13、痉为病$a{，一本痉字上有刚字}，胸满口噤，卧不着席，脚挛急，必齘齿，可与$f{大承气汤}。</p><p>14、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹。$a{《玉函》云中湿。}湿痹之候，小便不利，大便反快，但当利其小便。</p><p>15、湿家之为病，一身尽疼$a{一云疼烦}，发热，身色如熏黄也。</p><p>16、湿家其人但头汗出，背强，欲得被覆向火。若下之早则哕，或胸满，小便不利$a{一云利}，舌上如胎者，以丹田有热，胸上有寒，渴欲得饮而不能饮，则口燥烦也。</p><p>17、湿家下之，额上汗出，微喘，小便利$a{一云不利}者，死；若下利不止者亦死。</p><p>18、风湿相抟，一身尽疼痛，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者，何也？盖发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者发其汗，但微微似欲出汗者，风湿俱去也。</p><p>19、湿家病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故鼻塞，内药鼻中则愈。$a{《脉经》云：病人喘，而无湿家病以下至而喘十一字。}</p><p>20、湿家身烦疼，可与$f{麻黄加术汤}，发其汗为宜，慎不可以火攻之。</p><p>21、病者一身尽疼，发热，日晡所剧者，名风湿。此病伤于汗出当风，或久伤取冷所致也。可与$f{麻黄杏仁薏苡甘草汤}。</p><p>22、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。</p><p>23、伤寒八九日，风湿相抟，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{去桂加白术汤}主之。$a{金匮此处附方为$f{白术附子汤}}</p><p>24、风湿相抟，骨节疼烦，掣痛不得屈伸，近之则痛剧，汗出短气，小便不利，恶风不欲去衣，或身微肿者，$f{甘草附子汤}主之。</p><p>25、太阳中暍，发热恶寒，身重而疼痛，其脉弦细芤迟。小便已，洒洒然毛耸，手足逆冷，小有劳，身即热，口开，前板齿燥。若发其汗，则其恶寒甚；加温针，则发热甚；数下之，则淋甚。</p><p>26、太阳中热者，暍是也。汗出恶寒，身热而渴，$f{白虎加人参汤}主之。</p><p>27、太阳中暍，身热疼重而脉微弱，此以夏月伤冷水，水行皮中所致也。$f{一物瓜蒂汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":1,"no":2}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、太阳病，发热无汗，反恶寒者，名曰刚痉。 2、太阳病，发热汗出而不恶寒，名曰柔痉。 3、太阳病，发热，脉沉而细者，名曰痉，为难治。 4、太阳病，发汗太多，因致痉。 5、夫风病，下之则痉，复发汗，必拘急。 6、疮家虽身疼痛，不可发汗，汗出则痉。 7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗者，寒湿相得，其表益虚，即恶寒甚。发其汗已，其脉如蛇。 8、暴腹胀大者，为欲解，脉如故，反伏弦者，痉。 9、夫痉脉，按之紧如弦，直上下行。$a{一作筑筑而弦。《脉经》云：痉家其脉伏坚，直上下。} 10、痉病有灸疮，难治。 11、太阳病，其证备，身体强几几，然脉反沉迟，此为痉，$f{栝楼桂枝汤}主之。 12、太阳病，无汗而小便反少，气上冲胸，口噤不得语，欲作刚痉，$f{葛根汤}主之。 13、痉为病$a{，一本痉字上有刚字}，胸满口噤，卧不着席，脚挛急，必齘齿，可与$f{大承气汤}。 14、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹。$a{《玉函》云中湿。}湿痹之候，小便不利，大便反快，但当利其小便。 15、湿家之为病，一身尽疼$a{一云疼烦}，发热，身色如熏黄也。 16、湿家其人但头汗出，背强，欲得被覆向火。若下之早则哕，或胸满，小便不利$a{一云利}，舌上如胎者，以丹田有热，胸上有寒，渴欲得饮而不能饮，则口燥烦也。 17、湿家下之，额上汗出，微喘，小便利$a{一云不利}者，死；若下利不止者亦死。 18、风湿相抟，一身尽疼痛，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者，何也？盖发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者发其汗，但微微似欲出汗者，风湿俱去也。 19、湿家病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故鼻塞，内药鼻中则愈。$a{《脉经》云：病人喘，而无湿家病以下至而喘十一字。} 20、湿家身烦疼，可与$f{麻黄加术汤}，发其汗为宜，慎不可以火攻之。 21、病者一身尽疼，发热，日晡所剧者，名风湿。此病伤于汗出当风，或久伤取冷所致也。可与$f{麻黄杏仁薏苡甘草汤}。 22、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。 23、伤寒八九日，风湿相抟，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{去桂加白术汤}主之。$a{金匮此处附方为$f{白术附子汤}} 24、风湿相抟，骨节疼烦，掣痛不得屈伸，近之则痛剧，汗出短气，小便不利，恶风不欲去衣，或身微肿者，$f{甘草附子汤}主之。 25、太阳中暍，发热恶寒，身重而疼痛，其脉弦细芤迟。小便已，洒洒然毛耸，手足逆冷，小有劳，身即热，口开，前板齿燥。若发其汗，则其恶寒甚；加温针，则发热甚；数下之，则淋甚。 26、太阳中热者，暍是也。汗出恶寒，身热而渴，$f{白虎加人参汤}主之。 27、太阳中暍，身热疼重而脉微弱，此以夏月伤冷水，水行皮中所致也。$f{一物瓜蒂汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kQ4TW5Ncvxf', 1, '{"title":"金匮要略3  百合狐惑阴阳毒","description":"<p>1、论曰：百合病者，百脉一宗，悉致其病也。意欲食复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不用闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅然者，四十日愈；若溺快然，但头眩者，二十日愈。其证或未病而预见，或病四五日而出，或病二十日，或一月微见者，各随证治之。</p><p>2、百合病发汗后者，$f{百合知母汤}主之。</p><p>3、百合病下之后者，$f{滑石代赭汤}主之。</p><p>4、百合病吐之后者，$f{百合鸡子汤}主之。</p><p>5、百合病不经吐下发汗，病形如初者，$f{百合地黄汤}主之。</p><p>6、百合病一月不解，变成渴者，$f{百合洗}方主之。</p><p>7、百合病渴不差者，$f{栝楼牡蛎散}主之。</p><p>8、百合病变发热者，$a{一作发寒热。}$f{百合滑石散}主之。</p><p>9、百合病见于阴者，以阳法救之；见于阳者，以阴法救之。见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。</p><p>10、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐。不欲饮食，恶闻食臭，其面目乍赤、乍黑、乍白。蚀于上部则声喝$a{一作嗄}，$f{甘草泻心汤}主之。</p><p>11、蚀于下部则咽干，$f{苦参汤}洗之。</p><p>12、蚀于肛者，$f{雄黄}熏之。</p><p>13、病者脉数，无热，微烦，默默但欲卧，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦$a{一本此有黄字}黑，若能食者，脓已成也。$f{赤豆当归散}主之。</p><p>14、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血。五日可治，七日不可治。$f{升麻鳖甲汤}主之。</p><p>15、阴毒之为病，面目青，身痛如被杖，咽喉痛。五日可治，七日不可治，$f{升麻鳖甲汤}去$u{雄黄}、$u{蜀椒}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":2,"no":3}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、论曰：百合病者，百脉一宗，悉致其病也。意欲食复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不用闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅然者，四十日愈；若溺快然，但头眩者，二十日愈。其证或未病而预见，或病四五日而出，或病二十日，或一月微见者，各随证治之。 2、百合病发汗后者，$f{百合知母汤}主之。 3、百合病下之后者，$f{滑石代赭汤}主之。 4、百合病吐之后者，$f{百合鸡子汤}主之。 5、百合病不经吐下发汗，病形如初者，$f{百合地黄汤}主之。 6、百合病一月不解，变成渴者，$f{百合洗}方主之。 7、百合病渴不差者，$f{栝楼牡蛎散}主之。 8、百合病变发热者，$a{一作发寒热。}$f{百合滑石散}主之。 9、百合病见于阴者，以阳法救之；见于阳者，以阴法救之。见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。 10、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐。不欲饮食，恶闻食臭，其面目乍赤、乍黑、乍白。蚀于上部则声喝$a{一作嗄}，$f{甘草泻心汤}主之。 11、蚀于下部则咽干，$f{苦参汤}洗之。 12、蚀于肛者，$f{雄黄}熏之。 13、病者脉数，无热，微烦，默默但欲卧，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦$a{一本此有黄字}黑，若能食者，脓已成也。$f{赤豆当归散}主之。 14、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血。五日可治，七日不可治。$f{升麻鳖甲汤}主之。 15、阴毒之为病，面目青，身痛如被杖，咽喉痛。五日可治，七日不可治，$f{升麻鳖甲汤}去$u{雄黄}、$u{蜀椒}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ti5h73khf2s', 1, '{"title":"金匮要略4  疟病","description":"<p>1、师曰：疟脉自弦，弦数者多热，弦迟者多寒。弦小紧者，下之差，弦迟者，可温之；弦紧者，可发汗，针灸也；浮大者，可吐之；弦数者，风发也，以饮食消息止之。</p><p>2、病疟，以月一日发，当以十五日愈；设不差，当月尽解；如其不差，当云何？师曰：此结为癥瘕，名曰疟母，急治之，宜$f{鳖甲煎丸}。</p><p>3、师曰：阴气孤绝，阳气独发，则热而少气烦冤，手足热而欲呕，名曰瘅疟。若但热不寒者，邪气内藏于心，外舍分肉之间，令人消铄脱肉。</p><p>4、温疟者，其脉如平，身无寒但热，骨节疼烦，时呕，$f{白虎加桂枝汤}主之。</p><p>5、疟多寒者，名曰牡疟，$f{蜀漆散}主之。</p><p>*、$q{附《外台秘要》}$f{牡蛎汤} 治牡疟。</p><p>*、$q{附《外台秘要》}$f{柴胡去半夏加栝楼汤} 治疟病发渴者，亦治劳疟。</p><p>*、$q{附《外台秘要》}$f{柴胡桂枝干姜汤} 治疟寒多，微有热，或但寒不热。服一剂如神。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":3,"no":4}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、师曰：疟脉自弦，弦数者多热，弦迟者多寒。弦小紧者，下之差，弦迟者，可温之；弦紧者，可发汗，针灸也；浮大者，可吐之；弦数者，风发也，以饮食消息止之。 2、病疟，以月一日发，当以十五日愈；设不差，当月尽解；如其不差，当云何？师曰：此结为癥瘕，名曰疟母，急治之，宜$f{鳖甲煎丸}。 3、师曰：阴气孤绝，阳气独发，则热而少气烦冤，手足热而欲呕，名曰瘅疟。若但热不寒者，邪气内藏于心，外舍分肉之间，令人消铄脱肉。 4、温疟者，其脉如平，身无寒但热，骨节疼烦，时呕，$f{白虎加桂枝汤}主之。 5、疟多寒者，名曰牡疟，$f{蜀漆散}主之。 *、$q{附《外台秘要》}$f{牡蛎汤} 治牡疟。 *、$q{附《外台秘要》}$f{柴胡去半夏加栝楼汤} 治疟病发渴者，亦治劳疟。 *、$q{附《外台秘要》}$f{柴胡桂枝干姜汤} 治疟寒多，微有热，或但寒不热。服一剂如神。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zwUX1LcqUfN', 1, '{"title":"金匮要略5  中风历节","description":"<p>1、夫风之为病，当半身不遂；或但臂不遂者，此为痹。脉微而数，中风使然。</p><p>2、寸口脉浮而紧，紧则为寒，浮则为虚，寒虚相抟，邪在皮肤。浮者血虚，络脉空虚，贼邪不泻，或左或右；邪气反缓，正气即急，正气引邪，㖞僻不遂。邪在于络，肌肤不仁；邪在于经，即重不胜；邪入于腑，即不识人；邪入于脏，舌即难言，口吐涎。</p><p>*、$f{侯氏黑散} 治大风，四肢烦重，心中恶寒不足者。$q{《外台》}治风癫。</p><p>3、寸口脉迟而缓，迟则为寒，缓则为虚。营缓则为亡血，卫缓则为中风。邪气中经，则身痒而瘾疹；心气不足，邪气入中，则胸满而短气。</p><p>*、$f{风引汤} 除热瘫癎。</p><p>*、$f{防己地黄汤} 治病如狂状，妄行，独语不休，无寒热，其脉浮。</p><p>*、$f{头风摩散方}</p><p>4、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节黄汗出，故曰历节。</p><p>5、趺阳脉浮而滑，滑则谷气实，浮则汗自出。</p><p>6、少阴脉浮而弱，弱则血不足，浮则为风，风血相抟，即疼痛如掣。</p><p>7、盛人脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致。</p><p>8、诸肢节疼痛，身体尪羸，脚肿如脱，头眩短气，温温欲吐，$f{桂枝芍药知母汤}主之。</p><p>9、味酸则伤筋，筋伤则缓，名曰泄；咸则伤骨，骨伤则痿，名曰枯。枯泄相抟，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无所御，四属断绝，身体羸瘦。独足肿大，黄汗出，胫冷。假令发热，便为历节也。</p><p>10、病历节，不可屈伸，疼痛，$f{乌头汤}主之。</p><p>*、$f{矾石汤} 治脚气冲心</p><p>*、$q{附方《古今录验》}$f{续命汤} 治中风痱，身体不能自收持，口不能言，冒昧不知痛处，或拘急不得转侧。$a{姚云：与大续命同，兼治妇人产后出血者，及老人小儿。}</p><p>*、$q{《千金》}$f{三黄汤} 治中风手足拘急，百节疼痛，烦热心乱，恶寒，经日不欲饮食。</p><p>*、$q{《近效方》}$f{术附子汤} 治风虚头重眩，苦极，不知食味，暖肌补中，益精气。</p><p>*、$q{崔氏}$f{八味丸} 治脚气上入，少腹不仁。</p><p>*、$q{《千金方》}$f{越婢加术汤} 治肉极，热则身体津脱，腠理开，汗大泄，厉风气，下焦脚弱。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":4,"no":5}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、夫风之为病，当半身不遂；或但臂不遂者，此为痹。脉微而数，中风使然。 2、寸口脉浮而紧，紧则为寒，浮则为虚，寒虚相抟，邪在皮肤。浮者血虚，络脉空虚，贼邪不泻，或左或右；邪气反缓，正气即急，正气引邪，㖞僻不遂。邪在于络，肌肤不仁；邪在于经，即重不胜；邪入于腑，即不识人；邪入于脏，舌即难言，口吐涎。 *、$f{侯氏黑散} 治大风，四肢烦重，心中恶寒不足者。$q{《外台》}治风癫。 3、寸口脉迟而缓，迟则为寒，缓则为虚。营缓则为亡血，卫缓则为中风。邪气中经，则身痒而瘾疹；心气不足，邪气入中，则胸满而短气。 *、$f{风引汤} 除热瘫癎。 *、$f{防己地黄汤} 治病如狂状，妄行，独语不休，无寒热，其脉浮。 *、$f{头风摩散方} 4、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节黄汗出，故曰历节。 5、趺阳脉浮而滑，滑则谷气实，浮则汗自出。 6、少阴脉浮而弱，弱则血不足，浮则为风，风血相抟，即疼痛如掣。 7、盛人脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致。 8、诸肢节疼痛，身体尪羸，脚肿如脱，头眩短气，温温欲吐，$f{桂枝芍药知母汤}主之。 9、味酸则伤筋，筋伤则缓，名曰泄；咸则伤骨，骨伤则痿，名曰枯。枯泄相抟，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无所御，四属断绝，身体羸瘦。独足肿大，黄汗出，胫冷。假令发热，便为历节也。 10、病历节，不可屈伸，疼痛，$f{乌头汤}主之。 *、$f{矾石汤} 治脚气冲心 *、$q{附方《古今录验》}$f{续命汤} 治中风痱，身体不能自收持，口不能言，冒昧不知痛处，或拘急不得转侧。$a{姚云：与大续命同，兼治妇人产后出血者，及老人小儿。} *、$q{《千金》}$f{三黄汤} 治中风手足拘急，百节疼痛，烦热心乱，恶寒，经日不欲饮食。 *、$q{《近效方》}$f{术附子汤} 治风虚头重眩，苦极，不知食味，暖肌补中，益精气。 *、$q{崔氏}$f{八味丸} 治脚气上入，少腹不仁。 *、$q{《千金方》}$f{越婢加术汤} 治肉极，热则身体津脱，腠理开，汗大泄，厉风气，下焦脚弱。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QMamiO7b1M5', 1, '{"title":"金匮要略6  血痹虚劳","description":"<p>1、问曰：血痹病从何得之？师曰：夫尊荣人，骨弱肌肤盛，重因疲劳汗出，卧不时动摇，加被微风，遂得之。但以脉自微涩，在寸口、关上小紧，宜针引阳气，令脉和紧去则愈。</p><p>2、血痹阴阳俱微，寸口关上微，尺中小紧，外证身体不仁，如风痹状，$f{黄芪桂枝五物汤}主之。</p><p>3、夫男子平人，脉大为劳，极虚亦为劳。</p><p>4、男子面色薄者，主渴及亡血，卒喘悸，脉浮者，里虚也。</p><p>5、男子脉虚沉弦，无寒热，短气里急，小便不利，面色白，时目瞑，兼衄，少腹满，此为劳使之然。</p><p>6、劳之为病，其脉浮大，手足烦；春夏剧，秋冬瘥。阴寒精自出，酸削不能行。</p><p>7、男子脉浮弱而涩，为无子，精气清冷$a{一作冷}。</p><p>8、夫失精家，少腹弦急，阴头寒，目眩$a{一作目眶痛}，发落，脉极虚芤迟，为清谷、亡血、失精。脉得诸芤动微紧，男子失精，女子梦交，$f{桂枝加龙骨牡蛎汤}主之。</p><p>*、$f{天雄散}方</p><p>9、男子平人，脉虚弱细微者，善盗汗也。</p><p>10、人年五六十，其病脉大者，痹侠背行，若$a{宋本、赵本作苦}肠鸣，马刀侠瘿者，皆为劳得之。</p><p>11、脉沉小迟，名脱气。其人疾行则喘喝，手足逆寒，腹满，甚则溏泄，食不消化也。</p><p>12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，虚寒相抟，此名为革。妇人则半产漏下，男子则亡血失精。</p><p>13、虚劳里急，悸，衄，腹中痛，梦失精，四肢酸疼，手足烦热，咽干口燥，$f{小建中汤}主之。</p><p>14、虚劳里急，诸不足，$f{黄芪建中汤}主之。</p><p>15、虚劳腰痛，少腹拘急，小便不利者，$f{八味肾气丸}主之。$a{附方为$f{肾气丸}}</p><p>16、虚劳诸不足，风气百疾，$f{薯蓣丸}主之。</p><p>17、虚劳虚烦不得眠，$f{酸枣仁汤}主之。</p><p>18、五劳虚极羸瘦，腹满不能饮食，食伤、忧伤、饮伤、房室伤、饥伤、劳伤、经络荣卫气伤，内有干血，肌肤甲错，两目黯黑，缓中补虚，$f{大黄䗪虫丸}主之。</p><p>*、$q{附方《千金翼》}$f{炙甘草汤} $a{一云复脉汤。}治虚劳不足，汗出而闷，脉结悸，行动如常，不出百日，危急者，十一日死。</p><p>*、$q{《肘后》}$f{獭肝散} 治冷劳，又主鬼疰一门相染。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":5,"no":6}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、问曰：血痹病从何得之？师曰：夫尊荣人，骨弱肌肤盛，重因疲劳汗出，卧不时动摇，加被微风，遂得之。但以脉自微涩，在寸口、关上小紧，宜针引阳气，令脉和紧去则愈。 2、血痹阴阳俱微，寸口关上微，尺中小紧，外证身体不仁，如风痹状，$f{黄芪桂枝五物汤}主之。 3、夫男子平人，脉大为劳，极虚亦为劳。 4、男子面色薄者，主渴及亡血，卒喘悸，脉浮者，里虚也。 5、男子脉虚沉弦，无寒热，短气里急，小便不利，面色白，时目瞑，兼衄，少腹满，此为劳使之然。 6、劳之为病，其脉浮大，手足烦；春夏剧，秋冬瘥。阴寒精自出，酸削不能行。 7、男子脉浮弱而涩，为无子，精气清冷$a{一作冷}。 8、夫失精家，少腹弦急，阴头寒，目眩$a{一作目眶痛}，发落，脉极虚芤迟，为清谷、亡血、失精。脉得诸芤动微紧，男子失精，女子梦交，$f{桂枝加龙骨牡蛎汤}主之。 *、$f{天雄散}方 9、男子平人，脉虚弱细微者，善盗汗也。 10、人年五六十，其病脉大者，痹侠背行，若$a{宋本、赵本作苦}肠鸣，马刀侠瘿者，皆为劳得之。 11、脉沉小迟，名脱气。其人疾行则喘喝，手足逆寒，腹满，甚则溏泄，食不消化也。 12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，虚寒相抟，此名为革。妇人则半产漏下，男子则亡血失精。 13、虚劳里急，悸，衄，腹中痛，梦失精，四肢酸疼，手足烦热，咽干口燥，$f{小建中汤}主之。 14、虚劳里急，诸不足，$f{黄芪建中汤}主之。 15、虚劳腰痛，少腹拘急，小便不利者，$f{八味肾气丸}主之。$a{附方为$f{肾气丸}} 16、虚劳诸不足，风气百疾，$f{薯蓣丸}主之。 17、虚劳虚烦不得眠，$f{酸枣仁汤}主之。 18、五劳虚极羸瘦，腹满不能饮食，食伤、忧伤、饮伤、房室伤、饥伤、劳伤、经络荣卫气伤，内有干血，肌肤甲错，两目黯黑，缓中补虚，$f{大黄䗪虫丸}主之。 *、$q{附方《千金翼》}$f{炙甘草汤} $a{一云复脉汤。}治虚劳不足，汗出而闷，脉结悸，行动如常，不出百日，危急者，十一日死。 *、$q{《肘后》}$f{獭肝散} 治冷劳，又主鬼疰一门相染。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8maybAiexa1', 1, '{"title":"金匮要略7  肺痿肺痈咳嗽上气","description":"<p>1、问曰：热在上焦者，因咳为肺痿。肺痿之病，从何得之？师曰：或从汗出，或从呕吐，或从消渴，小便利数，或从便难，又被快药下利，重亡津液，故得之。曰：寸口脉数，其人咳，口中反有浊唾涎沫者何？师曰：为肺痿之病。若口中辟辟燥，咳即胸中隐隐痛，脉反滑数，此为肺痈，咳唾脓血。脉数虚者为肺痿，数实者为肺痈。</p><p>2、问曰：病咳逆，脉之何以知此为肺痈？当有脓血，吐之则死，其脉何类？师曰：寸口脉微而数，微则为风，数则为热；微则汗出，数则恶寒。风中于卫，呼气不入；热过于荣，吸而不出。风伤皮毛，热伤血脉。风舍于肺，其人则咳，口干喘满，咽燥不渴，时唾浊沫，时时振寒。热之所过，血为之凝滞，蓄结痈脓，吐如米粥。始萌可救，脓成则死。</p><p>3、上气面浮肿，肩息，其脉浮大，不治，又加利尤甚。</p><p>4、上气喘而躁者，属肺胀，欲作风水，发汗则愈。</p><p>5、肺痿吐涎沫而不咳者，其人不渴，必遗尿，小便数。所以然者，以上虚不能制下故也。此为肺中冷，必眩，多涎唾，$f{甘草干姜汤}以温之。若服汤已渴者，属消渴。</p><p>6、咳而上气，喉中水鸡声，$f{射干麻黄汤}主之。</p><p>7、咳逆上气，时时唾浊，但坐不得眠，$f{皂荚丸}主之。</p><p>8、咳而脉浮者，$f{厚朴麻黄汤}主之。</p><p>9、脉沉者，$f{泽漆汤}主之。</p><p>10、大逆上气，咽喉不利，止逆下气者，$f{麦门冬汤}主之。</p><p>11、肺痈，喘不得卧，$f{葶苈大枣泻肺汤}主之。</p><p>12、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈，$f{桔梗汤}主之。</p><p>13、咳而上气，此为肺胀，其人喘，目如脱状，脉浮大者，$f{越婢加半夏汤}主之。</p><p>14、肺胀，咳而上气，烦躁而喘，脉浮者，心下有水，$f{小青龙加石膏汤}主之。</p><p>*、$q{《外台》}$f{炙甘草汤}，治肺痿涎唾多，心中温温液液者。</p><p>*、$q{《千金》}$f{甘草汤} $a{此方本出于$q{《肘后》}而$q{《千金》}主疗，与$q{《外台》}炙甘草汤同，但唾多下，有出血二字。}</p><p>*、$q{《千金》}$f{生姜甘草汤} 治肺痿咳唾涎沫不止，咽燥而渴。</p><p>*、$q{《千金》}$f{桂枝去芍药加皂荚汤} 治肺痿吐涎沫。</p><p>*、$q{《外台》}$f{桔梗白散} 治咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈。</p><p>*、$q{《千金》}$f{苇茎汤} 治咳有微热烦满，胸中甲错，是为肺痈。</p><p>15、肺痈胸满胀，一身面目浮肿，鼻塞清涕出，不闻香臭酸辛，咳逆上气，喘鸣迫塞，$f{葶苈大枣泻肺汤}主之。$a{方见上，三日一剂，可至三四剂，此先服$f{小青龙汤}一剂乃进。$f{小青龙汤}方见咳嗽门中。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":6,"no":7}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、问曰：热在上焦者，因咳为肺痿。肺痿之病，从何得之？师曰：或从汗出，或从呕吐，或从消渴，小便利数，或从便难，又被快药下利，重亡津液，故得之。曰：寸口脉数，其人咳，口中反有浊唾涎沫者何？师曰：为肺痿之病。若口中辟辟燥，咳即胸中隐隐痛，脉反滑数，此为肺痈，咳唾脓血。脉数虚者为肺痿，数实者为肺痈。 2、问曰：病咳逆，脉之何以知此为肺痈？当有脓血，吐之则死，其脉何类？师曰：寸口脉微而数，微则为风，数则为热；微则汗出，数则恶寒。风中于卫，呼气不入；热过于荣，吸而不出。风伤皮毛，热伤血脉。风舍于肺，其人则咳，口干喘满，咽燥不渴，时唾浊沫，时时振寒。热之所过，血为之凝滞，蓄结痈脓，吐如米粥。始萌可救，脓成则死。 3、上气面浮肿，肩息，其脉浮大，不治，又加利尤甚。 4、上气喘而躁者，属肺胀，欲作风水，发汗则愈。 5、肺痿吐涎沫而不咳者，其人不渴，必遗尿，小便数。所以然者，以上虚不能制下故也。此为肺中冷，必眩，多涎唾，$f{甘草干姜汤}以温之。若服汤已渴者，属消渴。 6、咳而上气，喉中水鸡声，$f{射干麻黄汤}主之。 7、咳逆上气，时时唾浊，但坐不得眠，$f{皂荚丸}主之。 8、咳而脉浮者，$f{厚朴麻黄汤}主之。 9、脉沉者，$f{泽漆汤}主之。 10、大逆上气，咽喉不利，止逆下气者，$f{麦门冬汤}主之。 11、肺痈，喘不得卧，$f{葶苈大枣泻肺汤}主之。 12、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈，$f{桔梗汤}主之。 13、咳而上气，此为肺胀，其人喘，目如脱状，脉浮大者，$f{越婢加半夏汤}主之。 14、肺胀，咳而上气，烦躁而喘，脉浮者，心下有水，$f{小青龙加石膏汤}主之。 *、$q{《外台》}$f{炙甘草汤}，治肺痿涎唾多，心中温温液液者。 *、$q{《千金》}$f{甘草汤} $a{此方本出于$q{《肘后》}而$q{《千金》}主疗，与$q{《外台》}炙甘草汤同，但唾多下，有出血二字。} *、$q{《千金》}$f{生姜甘草汤} 治肺痿咳唾涎沫不止，咽燥而渴。 *、$q{《千金》}$f{桂枝去芍药加皂荚汤} 治肺痿吐涎沫。 *、$q{《外台》}$f{桔梗白散} 治咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈。 *、$q{《千金》}$f{苇茎汤} 治咳有微热烦满，胸中甲错，是为肺痈。 15、肺痈胸满胀，一身面目浮肿，鼻塞清涕出，不闻香臭酸辛，咳逆上气，喘鸣迫塞，$f{葶苈大枣泻肺汤}主之。$a{方见上，三日一剂，可至三四剂，此先服$f{小青龙汤}一剂乃进。$f{小青龙汤}方见咳嗽门中。}', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0hPa7ReM6m8', 1, '{"title":"金匮要略8  奔豚气病","description":"<p>1、师曰：病有奔豚，有吐脓，有惊怖，有火邪，此四部病，皆从惊发得之。师曰：奔豚病从少腹起，上冲咽喉，发作欲死，复还止，皆从惊恐得之。</p><p>2、奔豚气上冲胸，腹痛，往来寒热，$f{奔豚汤}主之。</p><p>3、发汗后，烧针令其汗，针处被寒，核起而赤者，必发奔豚，气从少腹上至心，灸其核上各一壮，与$f{桂枝加桂汤}主之。</p><p>4、发汗后，脐下悸者，欲作奔豚，$f{茯苓桂枝甘草大枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":7,"no":8}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、师曰：病有奔豚，有吐脓，有惊怖，有火邪，此四部病，皆从惊发得之。师曰：奔豚病从少腹起，上冲咽喉，发作欲死，复还止，皆从惊恐得之。 2、奔豚气上冲胸，腹痛，往来寒热，$f{奔豚汤}主之。 3、发汗后，烧针令其汗，针处被寒，核起而赤者，必发奔豚，气从少腹上至心，灸其核上各一壮，与$f{桂枝加桂汤}主之。 4、发汗后，脐下悸者，欲作奔豚，$f{茯苓桂枝甘草大枣汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iY9O5nR3dpv', 1, '{"title":"金匮要略9  胸痹心痛短气","description":"<p>1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛。所以然者，责其极虚也。今阳虚知在上焦，所以胸痹、心痛者，以其阴弦故也。</p><p>2、平人无寒热，短气不足以息者，实也。</p><p>3、胸痹之病，喘息咳唾，胸背痛，短气，寸口脉沉而迟，关上小紧数，$f{栝楼薤白白酒汤}主之。</p><p>4、胸痹不得卧，心痛彻背者，$f{栝楼薤白半夏汤}主之。</p><p>5、胸痹，心中痞气，气结在胸，胸满，胁下逆抢心，$f{枳实薤白桂枝汤}主之，$f{人参汤}亦主之。$a{宋本、俞本、赵本痞气作痞留。}</p><p>6、胸痹，胸中气塞，短气，$f{茯苓杏仁甘草汤}主之，$f{橘枳姜汤}亦主之。</p><p>7、胸痹缓急者，$f{薏苡附子散}主之。</p><p>8、心中痞，诸逆心悬痛，$f{桂枝生姜枳实汤}主之。</p><p>9、心痛彻背，背痛彻心，$f{乌头赤石脂丸}主之。</p><p>*、$f{九痛丸} 治九种心痛。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":8,"no":9}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛。所以然者，责其极虚也。今阳虚知在上焦，所以胸痹、心痛者，以其阴弦故也。 2、平人无寒热，短气不足以息者，实也。 3、胸痹之病，喘息咳唾，胸背痛，短气，寸口脉沉而迟，关上小紧数，$f{栝楼薤白白酒汤}主之。 4、胸痹不得卧，心痛彻背者，$f{栝楼薤白半夏汤}主之。 5、胸痹，心中痞气，气结在胸，胸满，胁下逆抢心，$f{枳实薤白桂枝汤}主之，$f{人参汤}亦主之。$a{宋本、俞本、赵本痞气作痞留。} 6、胸痹，胸中气塞，短气，$f{茯苓杏仁甘草汤}主之，$f{橘枳姜汤}亦主之。 7、胸痹缓急者，$f{薏苡附子散}主之。 8、心中痞，诸逆心悬痛，$f{桂枝生姜枳实汤}主之。 9、心痛彻背，背痛彻心，$f{乌头赤石脂丸}主之。 *、$f{九痛丸} 治九种心痛。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('15pc4Qe55iZ', 1, '{"title":"金匮要略10  腹满寒疝宿食","description":"<p>1、趺阳脉微弦，法当腹满，不满者必便难，两胠疼痛，此虚寒从下上也，当以温药服之。</p><p>2、病者腹满，按之不痛为虚，痛者为实，可下之。舌黄未下者，下之黄自去。</p><p>3、腹满时减，复如故，此为寒，当与温药。</p><p>4、病者痿黄，躁而不渴，胸中寒实而利不止者，死。</p><p>5、寸口脉弦者，即胁下拘急而痛，其人啬啬恶寒也。</p><p>6、夫中寒家，喜欠，其人清涕出，发热色和者，善嚏。</p><p>7、中寒，其人下利，以里虚也，欲嚏不能，此人肚中寒。$a{一云痛}</p><p>8、夫瘦人绕脐痛，必有风冷，谷气不行，而反下之，其气必冲。不冲者，心下则痞。</p><p>9、病腹满，发热十日，脉浮而数，饮食如故，$f{厚朴七物汤}主之。</p><p>10、腹中寒气，雷鸣切痛，胸胁逆满，呕吐，$f{附子粳米汤}主之。</p><p>11、痛而闭者，$f{厚朴三物汤}主之。</p><p>12、按之心下满痛者，此为实也，当下之，宜$f{大柴胡汤}。</p><p>13、腹满不减，减不足言，当须下之，宜$f{大承气汤}。</p><p>14、心胸中大寒痛，呕不能饮食，腹中寒，上冲皮起，出见有头足，上下痛而不可触近，$f{大建中汤}主之。</p><p>15、胁下偏痛，发热，其脉紧弦，此寒也，以温药下之，宜$f{大黄附子汤}。</p><p>16、寒气厥逆，$f{赤丸}主之。</p><p>17、腹痛，脉弦而紧，弦则卫气不行，即恶寒，紧则不欲食，邪正相抟，即为寒疝。寒疝绕脐痛，若发则白汗出，手足厥冷，其脉沉弦$a{（一云沉紧，一云弦）}者，$f{大乌头煎}主之。</p><p>18、寒疝腹中痛，及胁痛里急者，$f{当归生姜羊肉汤}主之。</p><p>19、寒疝腹中痛，逆冷，手足不仁，若身疼痛，灸、刺、诸药不能治，$a{抵当}$f{乌头桂枝汤}主之。    </p><p>20、其脉数而紧乃弦，状如弓弦，按之不移。脉数弦者，当下其寒；脉紧大而迟者，必心下坚；脉大而紧者，阳中有阴，可下之。</p><p>*、$q{《外台》}$f{乌头汤} 治寒疝腹中绞痛，贼风入攻五脏，拘急不得转侧，发作有时，使人阴缩，手足厥逆。</p><p>*、$q{《外台》}$f{柴胡桂枝汤} 治心腹卒中痛者。</p><p>*、$q{《外台》}$f{走马汤} 治中恶心痛腹胀，大便不通。</p><p>21、问曰：人病有宿食，何以别之？师曰：寸口脉浮而大，按之反涩，尺中亦微而涩，故知有宿食，$f{大承气汤}主之。</p><p>22、脉数而滑者，实也，此有宿食，下之愈，宜$f{大承气汤}。</p><p>23、下利不饮食者，有宿食也，当下之，宜$f{大承气汤}。</p><p>24、宿食在上脘，当吐之，宜$f{瓜蒂散}。</p><p>25、脉紧如转索无常者，有宿食也。</p><p>26、脉紧，头痛风寒，腹中有宿食不化也。$a{一云寸口脉紧。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":9,"no":10}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、趺阳脉微弦，法当腹满，不满者必便难，两胠疼痛，此虚寒从下上也，当以温药服之。 2、病者腹满，按之不痛为虚，痛者为实，可下之。舌黄未下者，下之黄自去。 3、腹满时减，复如故，此为寒，当与温药。 4、病者痿黄，躁而不渴，胸中寒实而利不止者，死。 5、寸口脉弦者，即胁下拘急而痛，其人啬啬恶寒也。 6、夫中寒家，喜欠，其人清涕出，发热色和者，善嚏。 7、中寒，其人下利，以里虚也，欲嚏不能，此人肚中寒。$a{一云痛} 8、夫瘦人绕脐痛，必有风冷，谷气不行，而反下之，其气必冲。不冲者，心下则痞。 9、病腹满，发热十日，脉浮而数，饮食如故，$f{厚朴七物汤}主之。 10、腹中寒气，雷鸣切痛，胸胁逆满，呕吐，$f{附子粳米汤}主之。 11、痛而闭者，$f{厚朴三物汤}主之。 12、按之心下满痛者，此为实也，当下之，宜$f{大柴胡汤}。 13、腹满不减，减不足言，当须下之，宜$f{大承气汤}。 14、心胸中大寒痛，呕不能饮食，腹中寒，上冲皮起，出见有头足，上下痛而不可触近，$f{大建中汤}主之。 15、胁下偏痛，发热，其脉紧弦，此寒也，以温药下之，宜$f{大黄附子汤}。 16、寒气厥逆，$f{赤丸}主之。 17、腹痛，脉弦而紧，弦则卫气不行，即恶寒，紧则不欲食，邪正相抟，即为寒疝。寒疝绕脐痛，若发则白汗出，手足厥冷，其脉沉弦$a{（一云沉紧，一云弦）}者，$f{大乌头煎}主之。 18、寒疝腹中痛，及胁痛里急者，$f{当归生姜羊肉汤}主之。 19、寒疝腹中痛，逆冷，手足不仁，若身疼痛，灸、刺、诸药不能治，$a{抵当}$f{乌头桂枝汤}主之。 20、其脉数而紧乃弦，状如弓弦，按之不移。脉数弦者，当下其寒；脉紧大而迟者，必心下坚；脉大而紧者，阳中有阴，可下之。 *、$q{《外台》}$f{乌头汤} 治寒疝腹中绞痛，贼风入攻五脏，拘急不得转侧，发作有时，使人阴缩，手足厥逆。 *、$q{《外台》}$f{柴胡桂枝汤} 治心腹卒中痛者。 *、$q{《外台》}$f{走马汤} 治中恶心痛腹胀，大便不通。 21、问曰：人病有宿食，何以别之？师曰：寸口脉浮而大，按之反涩，尺中亦微而涩，故知有宿食，$f{大承气汤}主之。 22、脉数而滑者，实也，此有宿食，下之愈，宜$f{大承气汤}。 23、下利不饮食者，有宿食也，当下之，宜$f{大承气汤}。 24、宿食在上脘，当吐之，宜$f{瓜蒂散}。 25、脉紧如转索无常者，有宿食也。 26、脉紧，头痛风寒，腹中有宿食不化也。$a{一云寸口脉紧。}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YX4g5S2TBwb', 1, '{"title":"金匮要略11  五脏风寒积聚","description":"<p>1、肺中风者，口燥而喘，身运而重，冒而肿胀。</p><p>2、肺中寒，吐浊涕。</p><p>3、肺死脏，浮之虚，按之弱如葱叶，下无根者，死。</p><p>4、肝中风者，头目瞤，两胁痛，行常伛，令人嗜甘。</p><p>5、肝中寒者，两臂不举，舌本燥，喜太息，胸中痛，不得转侧，食则吐而汗出也。$a{《脉经》、《千金》云：时盗汗，咳，食已吐其汁。}</p><p>6、肝死脏，浮之弱，按之如索不来，或曲如蛇行者，死。</p><p>7、肝着，其人常欲蹈其胸上，先未苦时，但欲饮热，$f{旋覆花汤}主之。$a{臣亿等校诸本旋覆花汤，皆同。同恐阙讹}</p><p>8、心中风者，翕翕发热，不能起，心中饥，食即呕吐。</p><p>9、心中寒者，其人苦病心如啖蒜状，剧者心痛彻背，背痛彻心，譬如蛊注。其脉浮者，自吐乃愈。</p><p>10、心伤者，其人劳倦，即头面赤而下重，心中痛而自烦，发热，当脐跳，其脉弦，此为心脏伤所致也。</p><p>11、心死脏，浮之实如麻豆，按之益躁疾者，死。</p><p>12、邪哭使魂魄不安者，血气少也；血气少者属于心，心气虚者，其人则畏，合目欲眠，梦远行而精神离散，魂魄妄行。阴气衰者为癫，阳气衰者为狂。</p><p>13、脾中风者，翕翕发热，形如醉人，腹中烦重，皮目瞤瞤而短气。</p><p>14、脾死脏，浮之大坚，按之如覆杯，洁洁状如摇者，死。$a{臣亿等详五脏各有中风中寒，今脾只载中风，肾中风中寒俱不载者，以古文简乱极多，去古既远，无他可以补缀也。}</p><p>15、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相抟，大便则坚，其脾为约，$f{麻子仁丸}主之。</p><p>16、肾着之病，其人身体重，腰中冷，如坐水中，形如水状，反不渴，小便自利，饮食如故，病属下焦，身劳汗出，衣$a{一作表}里冷湿，久久得之，腰以下冷痛，腹重如带五千钱，$f{甘草干姜茯苓白术汤}主之。$a{。《千金》作肾着汤}</p><p>17、肾死脏，浮之坚，按之乱如转丸，益下入尺中者，死。</p><p>18、问曰：三焦竭部，上焦竭善噫，何谓也？师曰：上焦受中焦气未和，不能消谷，故能噫耳。下焦竭，即遗溺失便，其气不和，不能自禁制，不须治，久则愈。</p><p>19、师曰：热在上焦者，因咳为肺痿；热在中焦者，则为坚；热在下焦者，则尿血，亦令淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便血；有热者，必痔。</p><p>20、问曰：病有积、有聚、有榖气，何谓也？师曰：积者，脏病也，终不移；聚者，府病也，发作有时，展转痛移，为可治；榖气者，胁下痛，按之则愈，复发为榖气。诸积大法：脉来细而附骨者，乃积也。寸口，积在胸中；微出寸口，积在喉中；关上，积在脐旁；上关上，积在心下；微下关，积在少腹。尺中，积在气冲；脉出左，积在左；脉出右，积在右；脉两出，积在中央。各以其部处之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":10,"no":11}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、肺中风者，口燥而喘，身运而重，冒而肿胀。 2、肺中寒，吐浊涕。 3、肺死脏，浮之虚，按之弱如葱叶，下无根者，死。 4、肝中风者，头目瞤，两胁痛，行常伛，令人嗜甘。 5、肝中寒者，两臂不举，舌本燥，喜太息，胸中痛，不得转侧，食则吐而汗出也。$a{《脉经》、《千金》云：时盗汗，咳，食已吐其汁。} 6、肝死脏，浮之弱，按之如索不来，或曲如蛇行者，死。 7、肝着，其人常欲蹈其胸上，先未苦时，但欲饮热，$f{旋覆花汤}主之。$a{臣亿等校诸本旋覆花汤，皆同。同恐阙讹} 8、心中风者，翕翕发热，不能起，心中饥，食即呕吐。 9、心中寒者，其人苦病心如啖蒜状，剧者心痛彻背，背痛彻心，譬如蛊注。其脉浮者，自吐乃愈。 10、心伤者，其人劳倦，即头面赤而下重，心中痛而自烦，发热，当脐跳，其脉弦，此为心脏伤所致也。 11、心死脏，浮之实如麻豆，按之益躁疾者，死。 12、邪哭使魂魄不安者，血气少也；血气少者属于心，心气虚者，其人则畏，合目欲眠，梦远行而精神离散，魂魄妄行。阴气衰者为癫，阳气衰者为狂。 13、脾中风者，翕翕发热，形如醉人，腹中烦重，皮目瞤瞤而短气。 14、脾死脏，浮之大坚，按之如覆杯，洁洁状如摇者，死。$a{臣亿等详五脏各有中风中寒，今脾只载中风，肾中风中寒俱不载者，以古文简乱极多，去古既远，无他可以补缀也。} 15、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相抟，大便则坚，其脾为约，$f{麻子仁丸}主之。 16、肾着之病，其人身体重，腰中冷，如坐水中，形如水状，反不渴，小便自利，饮食如故，病属下焦，身劳汗出，衣$a{一作表}里冷湿，久久得之，腰以下冷痛，腹重如带五千钱，$f{甘草干姜茯苓白术汤}主之。$a{。《千金》作肾着汤} 17、肾死脏，浮之坚，按之乱如转丸，益下入尺中者，死。 18、问曰：三焦竭部，上焦竭善噫，何谓也？师曰：上焦受中焦气未和，不能消谷，故能噫耳。下焦竭，即遗溺失便，其气不和，不能自禁制，不须治，久则愈。 19、师曰：热在上焦者，因咳为肺痿；热在中焦者，则为坚；热在下焦者，则尿血，亦令淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便血；有热者，必痔。 20、问曰：病有积、有聚、有榖气，何谓也？师曰：积者，脏病也，终不移；聚者，府病也，发作有时，展转痛移，为可治；榖气者，胁下痛，按之则愈，复发为榖气。诸积大法：脉来细而附骨者，乃积也。寸口，积在胸中；微出寸口，积在喉中；关上，积在脐旁；上关上，积在心下；微下关，积在少腹。尺中，积在气冲；脉出左，积在左；脉出右，积在右；脉两出，积在中央。各以其部处之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3N8wyjAR0z6', 1, '{"title":"金匮要略12  痰饮咳嗽","description":"<p>1、问曰：夫饮有四，何谓也？师曰：有痰饮，有悬饮，有溢饮，有支饮。</p><p>2、问曰：四饮何以为异？师曰：其人素盛今瘦，水走肠间，沥沥有声，谓之痰饮；饮后水流在胁下，咳唾引痛，谓之悬饮；饮水流行，归于四肢，当汗出而不汗出，身体疼重，谓之溢饮；咳逆倚息，短气不得卧，其形如肿，谓之支饮。</p><p>3、水在心，心下坚筑，短气，恶水不欲饮。</p><p>4、水在肺，吐涎沫，欲饮水。</p><p>5、水在脾，少气身重。</p><p>6、水在肝，胁下支满，嚏而痛。</p><p>7、水在肾，心下悸。</p><p>8、夫心下有留饮，其人背寒冷如手大。</p><p>9、留饮者，胁下痛引缺盆，咳嗽则辄已。$a{一作转甚。}</p><p>10、胸中有留饮，其人短气而渴，四肢历节痛。脉沉者，有留饮。</p><p>11、膈上病痰，满喘咳吐，发则寒热，背痛腰疼，目泣自出，其人振振身瞤剧，必有伏饮。</p><p>12、夫病人饮水多，必暴喘满。凡食少饮多，水停心下，甚者则悸，微者短气。脉双弦者，寒也，皆大下后善虚；脉偏弦者，饮也。</p><p>13、肺饮不弦，但苦喘短气。</p><p>14、支饮亦喘而不能卧，加短气，其脉平也。</p><p>15、病痰饮者，当以温药和之。</p><p>16、心下有痰饮，胸胁支满，目眩，$f{茯苓桂枝白术甘草汤}主之。</p><p>17、夫短气有微饮，当从小便去之，$f{茯苓桂枝白术甘草汤}主之，$f{肾气丸}亦主之。</p><p>18、病者脉伏，其人欲自利，利反快，虽利，心下续坚满，此为留饮欲去故也，$f{甘遂半夏汤}主之。</p><p>19、脉浮而细滑，伤饮。</p><p>20、脉弦数，有寒饮，冬夏难治。</p><p>21、脉沉而弦者，悬饮内痛。</p><p>22、病悬饮者，$f{十枣汤}主之。</p><p>23、病溢饮者，当发其汗，$f{大青龙汤}主之，$f{小青龙汤}亦主之。</p><p>24、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈，$f{木防己汤}主之。虚者即愈，实者三日复发。复与不愈者，宜$f{木防己去石膏加茯苓芒硝汤}主之。</p><p>25、心下有支饮，其人苦冒眩，$f{泽泻汤}主之。</p><p>26、支饮胸满者，$f{厚朴大黄汤}主之。</p><p>27、支饮不得息，$f{葶苈大枣泻肺汤}主之。</p><p>28、呕家本渴，渴者为欲解，今反不渴，$a{$q{《千金》}作呕家不渴，渴者为欲解，本渴今反不渴。}心下有支饮故也，$f{小半夏汤}主之。$a{$q{《千金》}云：$f{小半夏加茯苓汤}。}</p><p>29、腹满，口舌干燥，此肠间有水气，$f{己椒苈黄丸}主之。</p><p>30、卒呕吐，心下痞，膈间有水，眩悸者，$f{小半夏加茯苓汤}主之。</p><p>31、假令瘦人脐下有悸，吐涎沫而癫眩，此水也，$f{五苓散}主之。</p><p>*、$q{附方《外台》}$f{茯苓饮} 治心胸中有停痰宿水，自吐出水后，心胸间虚，气满不能食，消痰气，令能食。</p><p>32、咳家其脉弦，为有水，$f{十枣汤}主之。</p><p>33、夫有支饮家，咳烦，胸中痛者，不卒死，至一百日或一岁，宜$f{十枣汤}。</p><p>34、久咳数岁，其脉弱者可治，实大数者死；其脉虚者必苦冒，其人本有支饮在胸中故也，治属饮家。</p><p>35、咳逆倚息不得卧，$f{小青龙汤}主之。</p><p>36、$f{青龙汤}下已，多唾口燥，寸脉沉，尺脉微，手足厥逆，气从小腹上冲胸咽，手足痹，其面翕热如醉状，因复下流阴股，小便难，时复冒者，与$f{桂苓五味甘草汤}，治其气冲。</p><p>37、冲气即低，而反更咳，胸满者，用$f{桂苓五味甘草汤}去桂加$u{干姜}、$u{细辛}，以治其咳满。$a{即$f{苓甘五味姜辛汤}}</p><p>38、咳满即止，而更复渴，冲气复发者，以$u{细辛}、$u{干姜}为热药也。服之当遂渴，而渴反止者，为支饮也。支饮者，法当冒，冒者必呕，呕者复内$u{半夏}，以去其水。$a{即$f{桂苓五味甘草去桂加干姜细辛半夏汤}}</p><p>39、水去呕止，其人形肿者，加$u{杏仁}主之。其证应内$u{麻黄}，以其人遂痹，故不内之；若逆而内之者，必厥。所以然者，以其人血虚，$u{麻黄}发其阳故也。$a{即$f{苓甘五味加姜辛半夏杏仁汤}}</p><p>40、若面热如醉，此为胃热上冲，熏其面，加$u{大黄}以利之。$a{即$f{苓甘五味加姜辛半杏大黄汤}}</p><p>41、先渴后呕，为水停心下，此属饮家，$f{小半夏加茯苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":11,"no":12}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、问曰：夫饮有四，何谓也？师曰：有痰饮，有悬饮，有溢饮，有支饮。 2、问曰：四饮何以为异？师曰：其人素盛今瘦，水走肠间，沥沥有声，谓之痰饮；饮后水流在胁下，咳唾引痛，谓之悬饮；饮水流行，归于四肢，当汗出而不汗出，身体疼重，谓之溢饮；咳逆倚息，短气不得卧，其形如肿，谓之支饮。 3、水在心，心下坚筑，短气，恶水不欲饮。 4、水在肺，吐涎沫，欲饮水。 5、水在脾，少气身重。 6、水在肝，胁下支满，嚏而痛。 7、水在肾，心下悸。 8、夫心下有留饮，其人背寒冷如手大。 9、留饮者，胁下痛引缺盆，咳嗽则辄已。$a{一作转甚。} 10、胸中有留饮，其人短气而渴，四肢历节痛。脉沉者，有留饮。 11、膈上病痰，满喘咳吐，发则寒热，背痛腰疼，目泣自出，其人振振身瞤剧，必有伏饮。 12、夫病人饮水多，必暴喘满。凡食少饮多，水停心下，甚者则悸，微者短气。脉双弦者，寒也，皆大下后善虚；脉偏弦者，饮也。 13、肺饮不弦，但苦喘短气。 14、支饮亦喘而不能卧，加短气，其脉平也。 15、病痰饮者，当以温药和之。 16、心下有痰饮，胸胁支满，目眩，$f{茯苓桂枝白术甘草汤}主之。 17、夫短气有微饮，当从小便去之，$f{茯苓桂枝白术甘草汤}主之，$f{肾气丸}亦主之。 18、病者脉伏，其人欲自利，利反快，虽利，心下续坚满，此为留饮欲去故也，$f{甘遂半夏汤}主之。 19、脉浮而细滑，伤饮。 20、脉弦数，有寒饮，冬夏难治。 21、脉沉而弦者，悬饮内痛。 22、病悬饮者，$f{十枣汤}主之。 23、病溢饮者，当发其汗，$f{大青龙汤}主之，$f{小青龙汤}亦主之。 24、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈，$f{木防己汤}主之。虚者即愈，实者三日复发。复与不愈者，宜$f{木防己去石膏加茯苓芒硝汤}主之。 25、心下有支饮，其人苦冒眩，$f{泽泻汤}主之。 26、支饮胸满者，$f{厚朴大黄汤}主之。 27、支饮不得息，$f{葶苈大枣泻肺汤}主之。 28、呕家本渴，渴者为欲解，今反不渴，$a{$q{《千金》}作呕家不渴，渴者为欲解，本渴今反不渴。}心下有支饮故也，$f{小半夏汤}主之。$a{$q{《千金》}云：$f{小半夏加茯苓汤}。} 29、腹满，口舌干燥，此肠间有水气，$f{己椒苈黄丸}主之。 30、卒呕吐，心下痞，膈间有水，眩悸者，$f{小半夏加茯苓汤}主之。 31、假令瘦人脐下有悸，吐涎沫而癫眩，此水也，$f{五苓散}主之。 *、$q{附方《外台》}$f{茯苓饮} 治心胸中有停痰宿水，自吐出水后，心胸间虚，气满不能食，消痰气，令能食。 32、咳家其脉弦，为有水，$f{十枣汤}主之。 33、夫有支饮家，咳烦，胸中痛者，不卒死，至一百日或一岁，宜$f{十枣汤}。 34、久咳数岁，其脉弱者可治，实大数者死；其脉虚者必苦冒，其人本有支饮在胸中故也，治属饮家。 35、咳逆倚息不得卧，$f{小青龙汤}主之。 36、$f{青龙汤}下已，多唾口燥，寸脉沉，尺脉微，手足厥逆，气从小腹上冲胸咽，手足痹，其面翕热如醉状，因复下流阴股，小便难，时复冒者，与$f{桂苓五味甘草汤}，治其气冲。 37、冲气即低，而反更咳，胸满者，用$f{桂苓五味甘草汤}去桂加$u{干姜}、$u{细辛}，以治其咳满。$a{即$f{苓甘五味姜辛汤}} 38、咳满即止，而更复渴，冲气复发者，以$u{细辛}、$u{干姜}为热药也。服之当遂渴，而渴反止者，为支饮也。支饮者，法当冒，冒者必呕，呕者复内$u{半夏}，以去其水。$a{即$f{桂苓五味甘草去桂加干姜细辛半夏汤}} 39、水去呕止，其人形肿者，加$u{杏仁}主之。其证应内$u{麻黄}，以其人遂痹，故不内之；若逆而内之者，必厥。所以然者，以其人血虚，$u{麻黄}发其阳故也。$a{即$f{苓甘五味加姜辛半夏杏仁汤}} 40、若面热如醉，此为胃热上冲，熏其面，加$u{大黄}以利之。$a{即$f{苓甘五味加姜辛半杏大黄汤}} 41、先渴后呕，为水停心下，此属饮家，$f{小半夏加茯苓汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IpNd7TUi1u4', 1, '{"title":"金匮要略13  消渴小便不利淋病","description":"<p>1、厥阴之为病，消渴，气上冲心，心中疼热，饥而不欲食，食即吐，下之不肯止。</p><p>2、寸口脉浮而迟，浮即为虚，迟即为劳，虚则卫气不足，劳则荣$a{一云营}气竭。趺阳脉浮而数，浮即为气，数即消谷而大坚$a{一作紧}，气盛则溲数，溲数即坚，坚数相抟，即为消渴。</p><p>3、男子消渴，小便反多，以饮一斗，小便一斗，$f{肾气丸}主之。</p><p>4、脉浮，小便不利，微热消渴者，宜利小便、发汗，$f{五苓散}主之。</p><p>5、渴欲饮水，水入则吐者，名曰水逆，$f{五苓散}主之。</p><p>6、渴欲饮水不止者，$f{文蛤散}主之。</p><p>7、淋之为病，小便如粟状，小腹弦急，痛引脐中。</p><p>8、趺阳脉数，胃中有热，即消谷引食，大便必坚，小便即数。</p><p>9、淋家不可发汗，发汗则必便血。</p><p>10、小便不利者，有水气，其人若渴，$f{栝楼瞿麦丸}主之。</p><p>11、小便不利，$f{蒲灰散}主之，$f{滑石白鱼散}、$f{茯苓戎盐汤}并主之。</p><p>12、渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。</p><p>13、脉浮发热，渴欲饮水，小便不利者，$f{猪苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":12,"no":13}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、厥阴之为病，消渴，气上冲心，心中疼热，饥而不欲食，食即吐，下之不肯止。 2、寸口脉浮而迟，浮即为虚，迟即为劳，虚则卫气不足，劳则荣$a{一云营}气竭。趺阳脉浮而数，浮即为气，数即消谷而大坚$a{一作紧}，气盛则溲数，溲数即坚，坚数相抟，即为消渴。 3、男子消渴，小便反多，以饮一斗，小便一斗，$f{肾气丸}主之。 4、脉浮，小便不利，微热消渴者，宜利小便、发汗，$f{五苓散}主之。 5、渴欲饮水，水入则吐者，名曰水逆，$f{五苓散}主之。 6、渴欲饮水不止者，$f{文蛤散}主之。 7、淋之为病，小便如粟状，小腹弦急，痛引脐中。 8、趺阳脉数，胃中有热，即消谷引食，大便必坚，小便即数。 9、淋家不可发汗，发汗则必便血。 10、小便不利者，有水气，其人若渴，$f{栝楼瞿麦丸}主之。 11、小便不利，$f{蒲灰散}主之，$f{滑石白鱼散}、$f{茯苓戎盐汤}并主之。 12、渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。 13、脉浮发热，渴欲饮水，小便不利者，$f{猪苓汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wp5OKlKnUuK', 1, '{"title":"金匮要略14  水气病","description":"<p>1、师曰：病有风水，有皮水，有正水，有石水，有黄汗。风水，其脉自浮，外证骨节疼痛，恶风；皮水，其脉亦浮，外证胕肿，按之没指，不恶风，其腹如鼓，不渴，当发其汗；正水，其脉沉迟，外证自喘；石水，其脉自沉，外证腹满不喘；黄汗，其脉沉迟，身发热，胸满，四肢头面肿，久不愈，必致痈脓。</p><p>2、脉浮而洪，浮则为风，洪则为气，风气相抟，风强则为隐疹，身体为痒，痒为泄风，久为痂癞；气强则为水，难以俯仰。风气相击，身体洪肿，汗出乃愈。恶风则虚，此为风水；不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。</p><p>3、寸口脉沉滑者，中有水气，面目肿大，有热，名曰风水。视人之目窠上微拥，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，风水。</p><p>4、太阳病，脉浮而紧，法当骨节疼痛，反不疼，身体反重而酸，其人不渴，汗出即愈，此为风水。恶寒者，此为极虚，发汗得之。渴而不恶寒者，此为皮水。身肿而冷，状如周痹，胸中窒，不能食，反聚痛，暮躁不得眠，此为黄汗，痛在骨节。咳而喘，不渴者，此为脾胀，其状如肿，发汗即愈。然诸病此者，渴而下利，小便数者，皆不可发汗。</p><p>5、里水者，一身面目黄肿，其脉沉，小便不利，故令病水。假如小便自利，此亡津液，故令渴也。$f{越婢加术汤}主之。</p><p>6、趺阳脉当伏，今反紧，本自有寒，疝瘕，腹中痛，医反下之，下之即胸满短气。</p><p>7、趺阳脉当伏，今反数，本自有热，消谷，小便数，今反不利，此欲作水。</p><p>8、寸口脉浮而迟，浮脉则热，迟脉则潜，热潜相抟，名目沉。趺阳脉浮而数，浮脉即热，数脉即止，热止相抟，名曰伏。沉伏相抟，名曰水。沉则脉络虚，伏则小便难，虚难相抟，水走皮肤，即为水矣。</p><p>9、寸口脉弦而紧，弦则卫气不行，即恶寒，水不沾流，走于肠间。少阴脉紧而沉，紧则为痛，沉则为水，小便即难。</p><p>10、脉得诸沉，当责有水，身体肿重。水病脉出者死。</p><p>11、夫水病人，目下有卧蚕，面目鲜泽，脉伏，其人消渴。病水腹大，小便不利，其脉沉绝者，有水，可下之。</p><p>12、问曰：病下利后，渴饮水，小便不利，腹满因肿者，何也？答曰：此法当病水，若小便自利及汗出者，自当愈。</p><p>13、心水者，其身重而少气，不得卧，烦而躁，其人阴肿。</p><p>14、肝水者，其腹大，不能自转侧，胁下腹痛，时时津液微生，小便续通。</p><p>15、肺水者，其身肿，小便难，时时鸭溏。</p><p>16、脾水者，其腹大，四肢苦重，津液不生，但苦少气，小便难。</p><p>17、肾水者，其腹大，脐肿腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。</p><p>18、师曰：诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。</p><p>19、师曰：寸口脉沉而迟，沉则为水，迟则为寒，寒水相抟。趺阳脉伏，水谷不化，脾气衰则鹜溏，胃气衰则身肿。少阳脉卑，少阴脉细，男子则小便不利，妇人则经水不通。经为血，血不利则为水，名曰血分。</p><p>20、问曰：病有血分、水分，何也？师曰：经水前断，后病水，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治。何以故？去水，其经自下。$a{此条原本缺，据《脉经》及其他注本补入。}</p><p>21、问曰：病者苦水，面目身体四肢皆肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽，状如炙肉，当微咳喘。审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相抟，结在关元，始时当微，年盛不觉。阳衰之后，营卫相干，阳损阴盛，结寒微动，肾气上冲，喉咽塞噎，胁下急痛。医以为留饮而大下之，气击不去，其病不除。后重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿。又以葶苈丸下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则浮咳喘逆。当先攻击冲气，令止，乃治咳，咳止，其喘自差。先治新病，病当在后。</p><p>22、风水，脉浮身重，汗出恶风者，$f{防己黄芪汤}主之。腹痛加$u{芍药}。</p><p>23、风水恶风，一身悉肿，脉浮不渴，续自汗出，无大热，$f{越婢汤}主之。</p><p>24、皮水为病，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防己茯苓汤}主之。</p><p>25、里水，$f{越婢加术汤}主之，$f{甘草麻黄汤}亦主之。</p><p>26、水之为病，其脉沉小，属少阴；浮者为风；无水，虚胀者，为气。水，发其汗即已。脉沉者，宜$f{麻黄附子汤}；浮者，宜$f{杏子汤}。</p><p>27、厥而皮水者，$f{蒲灰散}主之。</p><p>28、问曰：黄汗之为病，身体肿，$a{一作重}，发热汗出而渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，何从得之？师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝苦酒汤}主之。</p><p>29、黄汗之病，两胫自冷。假令发热，此属历节。食已汗出，又身常暮盗汗出者，此劳气也。若汗出已，反发热者，久久其身必甲错；发热不止者，必生恶疮。若身重，汗出已辄轻者，久久必身瞤。瞤即胸中痛，又从腰以上必汗出，下无汗，腰髋弛痛，如有物在皮中状，剧者不能食，身疼重，烦躁，小便不利，此为黄汗。$f{桂枝加黄芪汤}主之。</p><p>30、师曰：寸口脉迟而涩，迟则为寒，涩为血不足。趺阳脉微而迟，微则为气，迟则为寒。寒气不足，则手足逆冷；手足逆冷，则荣卫不利；荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼；阳前通则恶寒，阴前通则痹不仁；阴阳相得，其气乃行，大气一转，其气乃散；实则失气，虚则遗尿，名曰气分。</p><p>31、气分，心下坚，大如盘，边如旋杯，水饮所作，$f{桂枝去芍药加麻黄细辛附子汤}主之。</p><p>32、心下坚，大如盘，边如旋盘，水饮所作，$f{枳术汤}主之。</p><p>*、$q{附方《外台》}$f{防己黄芪汤} 治风水，脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":13,"no":14}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、师曰：病有风水，有皮水，有正水，有石水，有黄汗。风水，其脉自浮，外证骨节疼痛，恶风；皮水，其脉亦浮，外证胕肿，按之没指，不恶风，其腹如鼓，不渴，当发其汗；正水，其脉沉迟，外证自喘；石水，其脉自沉，外证腹满不喘；黄汗，其脉沉迟，身发热，胸满，四肢头面肿，久不愈，必致痈脓。 2、脉浮而洪，浮则为风，洪则为气，风气相抟，风强则为隐疹，身体为痒，痒为泄风，久为痂癞；气强则为水，难以俯仰。风气相击，身体洪肿，汗出乃愈。恶风则虚，此为风水；不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。 3、寸口脉沉滑者，中有水气，面目肿大，有热，名曰风水。视人之目窠上微拥，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，风水。 4、太阳病，脉浮而紧，法当骨节疼痛，反不疼，身体反重而酸，其人不渴，汗出即愈，此为风水。恶寒者，此为极虚，发汗得之。渴而不恶寒者，此为皮水。身肿而冷，状如周痹，胸中窒，不能食，反聚痛，暮躁不得眠，此为黄汗，痛在骨节。咳而喘，不渴者，此为脾胀，其状如肿，发汗即愈。然诸病此者，渴而下利，小便数者，皆不可发汗。 5、里水者，一身面目黄肿，其脉沉，小便不利，故令病水。假如小便自利，此亡津液，故令渴也。$f{越婢加术汤}主之。 6、趺阳脉当伏，今反紧，本自有寒，疝瘕，腹中痛，医反下之，下之即胸满短气。 7、趺阳脉当伏，今反数，本自有热，消谷，小便数，今反不利，此欲作水。 8、寸口脉浮而迟，浮脉则热，迟脉则潜，热潜相抟，名目沉。趺阳脉浮而数，浮脉即热，数脉即止，热止相抟，名曰伏。沉伏相抟，名曰水。沉则脉络虚，伏则小便难，虚难相抟，水走皮肤，即为水矣。 9、寸口脉弦而紧，弦则卫气不行，即恶寒，水不沾流，走于肠间。少阴脉紧而沉，紧则为痛，沉则为水，小便即难。 10、脉得诸沉，当责有水，身体肿重。水病脉出者死。 11、夫水病人，目下有卧蚕，面目鲜泽，脉伏，其人消渴。病水腹大，小便不利，其脉沉绝者，有水，可下之。 12、问曰：病下利后，渴饮水，小便不利，腹满因肿者，何也？答曰：此法当病水，若小便自利及汗出者，自当愈。 13、心水者，其身重而少气，不得卧，烦而躁，其人阴肿。 14、肝水者，其腹大，不能自转侧，胁下腹痛，时时津液微生，小便续通。 15、肺水者，其身肿，小便难，时时鸭溏。 16、脾水者，其腹大，四肢苦重，津液不生，但苦少气，小便难。 17、肾水者，其腹大，脐肿腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。 18、师曰：诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。 19、师曰：寸口脉沉而迟，沉则为水，迟则为寒，寒水相抟。趺阳脉伏，水谷不化，脾气衰则鹜溏，胃气衰则身肿。少阳脉卑，少阴脉细，男子则小便不利，妇人则经水不通。经为血，血不利则为水，名曰血分。 20、问曰：病有血分、水分，何也？师曰：经水前断，后病水，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治。何以故？去水，其经自下。$a{此条原本缺，据《脉经》及其他注本补入。} 21、问曰：病者苦水，面目身体四肢皆肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽，状如炙肉，当微咳喘。审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相抟，结在关元，始时当微，年盛不觉。阳衰之后，营卫相干，阳损阴盛，结寒微动，肾气上冲，喉咽塞噎，胁下急痛。医以为留饮而大下之，气击不去，其病不除。后重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿。又以葶苈丸下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则浮咳喘逆。当先攻击冲气，令止，乃治咳，咳止，其喘自差。先治新病，病当在后。 22、风水，脉浮身重，汗出恶风者，$f{防己黄芪汤}主之。腹痛加$u{芍药}。 23、风水恶风，一身悉肿，脉浮不渴，续自汗出，无大热，$f{越婢汤}主之。 24、皮水为病，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防己茯苓汤}主之。 25、里水，$f{越婢加术汤}主之，$f{甘草麻黄汤}亦主之。 26、水之为病，其脉沉小，属少阴；浮者为风；无水，虚胀者，为气。水，发其汗即已。脉沉者，宜$f{麻黄附子汤}；浮者，宜$f{杏子汤}。 27、厥而皮水者，$f{蒲灰散}主之。 28、问曰：黄汗之为病，身体肿，$a{一作重}，发热汗出而渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，何从得之？师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝苦酒汤}主之。 29、黄汗之病，两胫自冷。假令发热，此属历节。食已汗出，又身常暮盗汗出者，此劳气也。若汗出已，反发热者，久久其身必甲错；发热不止者，必生恶疮。若身重，汗出已辄轻者，久久必身瞤。瞤即胸中痛，又从腰以上必汗出，下无汗，腰髋弛痛，如有物在皮中状，剧者不能食，身疼重，烦躁，小便不利，此为黄汗。$f{桂枝加黄芪汤}主之。 30、师曰：寸口脉迟而涩，迟则为寒，涩为血不足。趺阳脉微而迟，微则为气，迟则为寒。寒气不足，则手足逆冷；手足逆冷，则荣卫不利；荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼；阳前通则恶寒，阴前通则痹不仁；阴阳相得，其气乃行，大气一转，其气乃散；实则失气，虚则遗尿，名曰气分。 31、气分，心下坚，大如盘，边如旋杯，水饮所作，$f{桂枝去芍药加麻黄细辛附子汤}主之。 32、心下坚，大如盘，边如旋盘，水饮所作，$f{枳术汤}主之。 *、$q{附方《外台》}$f{防己黄芪汤} 治风水，脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r695ZbvlfYe', 1, '{"title":"金匮要略15  黄疸","description":"<p>1、寸口脉浮而缓，浮则为风，缓则为痹。痹非中风。四肢苦烦，脾色必黄，瘀热以行。</p><p>2、趺阳脉紧而数，数则为热，热则消谷，紧则为寒，食即为满。尺脉浮为伤肾，趺阳脉紧为伤脾。风寒相抟，食谷即眩，谷气不消，胃中苦浊，浊气下流，小便不通，阴被其寒，热流膀胱，身体尽黄，名曰谷疸。额上黑，微汗出，手足中热，薄暮即发，膀胱急，小便自利，名曰女劳疸，腹如水状不治。心中懊憹而热，不能食，时欲吐，名曰酒疸。</p><p>3、阳明病，脉迟者，食难用饱，饱则发烦头眩，小便必难，此欲作谷疸。虽下之，腹满如故，所以然者，脉迟故也。</p><p>4、夫病酒黄疸，必小便不利，其候心中热，足下热，是其证也。</p><p>5、酒黄疸者，或无热，靖言了$a{《脉经》作了了}，腹满欲吐，鼻燥。其脉浮者，先吐之；沉弦者，先下之。</p><p>6、酒疸，心中热，欲呕者，吐之愈。</p><p>7、酒疸下之，久久为黑疸，目青面黑，心中如啖蒜齑状，大便正黑，皮肤爪之不仁，其脉浮弱，虽黑微黄，故知之。</p><p>8、师曰：病黄疸，发热烦喘，胸满口燥者，以病发时，火劫其汗，两热所得。然黄家所得，从湿得之。一身尽发热而黄，肚热，热在里，当下之。</p><p>9、脉沉，渴欲饮水，小便不利者，皆发黄。</p><p>10、腹满，舌痿黄，燥不得睡，属黄家。$a{舌痿疑作身痿}</p><p>11、黄疸之病，当以十八日为期，治之十日以上瘥，反剧为难治。</p><p>12、疸而渴者，其疸难治；疸而不渴者，其疸可治。发于阴部，其人必呕；阳部，其人振寒而发热也。</p><p>13、谷疸之为病，寒热不食，食即头眩，心胸不安，久久发黄，为谷疸，$f{茵陈蒿汤}主之。</p><p>14、黄家日晡所发热，而反恶寒，此为女劳得之。膀胱急，少腹满，身尽黄，额上黑，足下热，因作黑疸。其腹胀如水状，大便必黑，时溏，此女劳之病，非水也。腹满者难治，$f{硝石矾石散}主之。</p><p>15、酒黄疸，心中懊憹或热痛，$f{栀子大黄汤}主之。</p><p>16、诸病黄家，但利其小便。假令脉浮，当以汗解之，宜$f{桂枝加黄芪汤}主之。</p><p>17、诸黄，$f{猪膏发煎}主之。</p><p>18、黄疸病，$f{茵陈五苓散}主之。$a{一本云茵陈汤及五苓散并主之。}</p><p>19、黄疸腹满，小便不利而赤，自汗出，此为表和里实，当下之，宜$f{大黄硝石汤}。</p><p>20、黄疸病，小便色不变，欲自利，腹满而喘，不可除热，热除必哕。哕者，$f{小半夏汤}主之。</p><p>21、诸黄，腹痛而呕者，宜$f{柴胡汤}。$a{必$f{小柴胡汤}。}</p><p>22、男子黄，小便自利，当与虚劳$f{小建中汤}。</p><p>*、$f{瓜蒂汤} 治诸黄。</p><p>*、$q{《千金》}$f{麻黄醇酒汤} 治黄疸。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":14,"no":15}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、寸口脉浮而缓，浮则为风，缓则为痹。痹非中风。四肢苦烦，脾色必黄，瘀热以行。 2、趺阳脉紧而数，数则为热，热则消谷，紧则为寒，食即为满。尺脉浮为伤肾，趺阳脉紧为伤脾。风寒相抟，食谷即眩，谷气不消，胃中苦浊，浊气下流，小便不通，阴被其寒，热流膀胱，身体尽黄，名曰谷疸。额上黑，微汗出，手足中热，薄暮即发，膀胱急，小便自利，名曰女劳疸，腹如水状不治。心中懊憹而热，不能食，时欲吐，名曰酒疸。 3、阳明病，脉迟者，食难用饱，饱则发烦头眩，小便必难，此欲作谷疸。虽下之，腹满如故，所以然者，脉迟故也。 4、夫病酒黄疸，必小便不利，其候心中热，足下热，是其证也。 5、酒黄疸者，或无热，靖言了$a{《脉经》作了了}，腹满欲吐，鼻燥。其脉浮者，先吐之；沉弦者，先下之。 6、酒疸，心中热，欲呕者，吐之愈。 7、酒疸下之，久久为黑疸，目青面黑，心中如啖蒜齑状，大便正黑，皮肤爪之不仁，其脉浮弱，虽黑微黄，故知之。 8、师曰：病黄疸，发热烦喘，胸满口燥者，以病发时，火劫其汗，两热所得。然黄家所得，从湿得之。一身尽发热而黄，肚热，热在里，当下之。 9、脉沉，渴欲饮水，小便不利者，皆发黄。 10、腹满，舌痿黄，燥不得睡，属黄家。$a{舌痿疑作身痿} 11、黄疸之病，当以十八日为期，治之十日以上瘥，反剧为难治。 12、疸而渴者，其疸难治；疸而不渴者，其疸可治。发于阴部，其人必呕；阳部，其人振寒而发热也。 13、谷疸之为病，寒热不食，食即头眩，心胸不安，久久发黄，为谷疸，$f{茵陈蒿汤}主之。 14、黄家日晡所发热，而反恶寒，此为女劳得之。膀胱急，少腹满，身尽黄，额上黑，足下热，因作黑疸。其腹胀如水状，大便必黑，时溏，此女劳之病，非水也。腹满者难治，$f{硝石矾石散}主之。 15、酒黄疸，心中懊憹或热痛，$f{栀子大黄汤}主之。 16、诸病黄家，但利其小便。假令脉浮，当以汗解之，宜$f{桂枝加黄芪汤}主之。 17、诸黄，$f{猪膏发煎}主之。 18、黄疸病，$f{茵陈五苓散}主之。$a{一本云茵陈汤及五苓散并主之。} 19、黄疸腹满，小便不利而赤，自汗出，此为表和里实，当下之，宜$f{大黄硝石汤}。 20、黄疸病，小便色不变，欲自利，腹满而喘，不可除热，热除必哕。哕者，$f{小半夏汤}主之。 21、诸黄，腹痛而呕者，宜$f{柴胡汤}。$a{必$f{小柴胡汤}。} 22、男子黄，小便自利，当与虚劳$f{小建中汤}。 *、$f{瓜蒂汤} 治诸黄。 *、$q{《千金》}$f{麻黄醇酒汤} 治黄疸。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R0pMgK52NFe', 1, '{"title":"金匮要略16  惊悸吐血下血胸满瘀血","description":"<p>1、寸口脉动而弱，动即为惊，弱则为悸。</p><p>2、师曰：尺脉浮，目睛晕黄，衄未止；晕黄去，目睛慧了，知衄今止。</p><p>3、又曰：从春至夏衄者太阳；从秋至冬衄者阳明。</p><p>4、衄家不可汗，汗出必额上陷，脉紧急，直视不能眴，不得眠。</p><p>5、病人面无色，无寒热，脉沉弦者，衄；浮弱，手按之绝者，下血；烦咳者，必吐血。</p><p>6、夫吐血，咳逆上气，其脉数而有热，不得卧者，死。</p><p>7、夫酒客咳者，必致吐血，此因极饮过度所致也。</p><p>8、寸口脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，寒虚相击，此名曰革，妇人则半产漏下，男子则亡血。</p><p>9、亡血不可发其表，汗出即寒栗而振。</p><p>10、病人胸满，唇痿舌青，口燥，但欲嗽水不欲咽，无寒热，脉微大来迟，腹不满，其人言我满，为有瘀血。</p><p>11、病者如热状，烦满，口干燥而渴，其脉反无热，此为阴伏，是瘀血也，当下之。</p><p>12、火邪者，$f{桂枝去芍药加蜀漆牡蛎龙骨救逆汤}主之。</p><p>13、心下悸者，$f{半夏麻黄丸}主之。</p><p>14、吐血不止者，$f{柏叶汤}主之。</p><p>15、下血，先便后血，此远血也，$f{黄土汤}主之。</p><p>16、下血，先血后便，此近血也，$f{赤豆当归散}主之。</p><p>17、心气不足$a{，$q{《千金》}为心气不定}，吐血，衄血，$f{泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":15,"no":16}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、寸口脉动而弱，动即为惊，弱则为悸。 2、师曰：尺脉浮，目睛晕黄，衄未止；晕黄去，目睛慧了，知衄今止。 3、又曰：从春至夏衄者太阳；从秋至冬衄者阳明。 4、衄家不可汗，汗出必额上陷，脉紧急，直视不能眴，不得眠。 5、病人面无色，无寒热，脉沉弦者，衄；浮弱，手按之绝者，下血；烦咳者，必吐血。 6、夫吐血，咳逆上气，其脉数而有热，不得卧者，死。 7、夫酒客咳者，必致吐血，此因极饮过度所致也。 8、寸口脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，寒虚相击，此名曰革，妇人则半产漏下，男子则亡血。 9、亡血不可发其表，汗出即寒栗而振。 10、病人胸满，唇痿舌青，口燥，但欲嗽水不欲咽，无寒热，脉微大来迟，腹不满，其人言我满，为有瘀血。 11、病者如热状，烦满，口干燥而渴，其脉反无热，此为阴伏，是瘀血也，当下之。 12、火邪者，$f{桂枝去芍药加蜀漆牡蛎龙骨救逆汤}主之。 13、心下悸者，$f{半夏麻黄丸}主之。 14、吐血不止者，$f{柏叶汤}主之。 15、下血，先便后血，此远血也，$f{黄土汤}主之。 16、下血，先血后便，此近血也，$f{赤豆当归散}主之。 17、心气不足$a{，$q{《千金》}为心气不定}，吐血，衄血，$f{泻心汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oD03MgEA8f2', 1, '{"title":"金匮要略17  呕吐哕下利","description":"<p>1、夫呕家有痈脓，不可治呕，脓尽自愈。</p><p>2、先呕却渴者，此为欲解；先渴却呕者，为水停心下，此属饮家。呕家本渴，今反不渴者，以心下有支饮故也，此属支饮。</p><p>3、问曰：病人脉数，数为热，当消谷引食，而反吐者，何也？师曰：以发其汗，令阳微，膈气虚，脉乃数。数为客热，不能消谷，胃中虚冷故也。脉弦者，虚也，胃气无余，朝食暮吐，变为胃反。寒在于上，医反下之，今脉反弦，故名曰虚。</p><p>4、寸口脉微而数，微则无气，无气则荣虚，荣虚则血不足，血不足则胸中冷。</p><p>5、趺阳脉浮而涩，浮则为虚，涩则伤脾，脾伤则不磨，朝食暮吐，暮食朝吐，宿谷不化，名曰胃反。脉紧而涩，其病难治。</p><p>6、病人欲吐者，不可下之。</p><p>7、哕而腹满，视其前后，知何部不利，利之即愈。</p><p>8、呕而胸满者，$f{吴茱萸汤}主之。</p><p>9、干呕吐涎沫，头痛者，$f{吴茱萸汤}主之。</p><p>10、呕而肠鸣，心下痞者，$f{半夏泻心汤}主之。</p><p>11、干呕而利者，$f{黄芩加半夏生姜汤}主之。</p><p>12、诸呕吐，谷不得下者，$f{小半夏汤}主之。</p><p>13、呕吐而病在膈上，后思水者，解，急与之。思水者，$f{猪苓散}主之。</p><p>14、呕而脉弱，小便复利，身有微热，见厥者难治，$f{四逆汤}主之。</p><p>15、呕而发热者，$f{小柴胡汤}主之。</p><p>16、胃反呕吐者，$f{大半夏汤}主之。$a{$q{《千金》}云：治胃反不受食，食入即吐。$q{《外台》}云：治呕，心下痞硬者。}</p><p>17、食已即吐者，$f{大黄甘草汤}主之。$a{$q{《外台》}方：又治吐水。}</p><p>18、胃反，吐而渴欲饮水者，$f{茯苓泽泻汤}主之。</p><p>19、吐后，渴欲得水而贪饮者，$f{文蛤汤}主之，兼主微风，脉紧，头痛。</p><p>20、干呕，吐逆，吐涎沫，$f{半夏干姜散}主之。</p><p>21、病人胸中似喘不喘，似呕不呕，似哕不哕，彻心中愦愦然无奈者，$f{生姜半夏汤}主之。</p><p>22、干呕、哕，若手足厥者，$f{橘皮汤}主之。</p><p>23、哕逆者，$f{橘皮竹茹汤}主之。</p><p>24、夫六腑气绝于外者，手足寒，上气，脚缩；五脏气绝于内者，利不禁，下甚者，手足不仁。</p><p>25、下利，脉沉弦者，下重；脉大者，为未止；脉微弱数者，为欲自止，虽发热不死。</p><p>26、下利，手足厥冷，无脉者，灸之不温。若脉不还，反微喘者，死。少阴负趺阳者，为顺也。</p><p>27、下利，有微热而渴，脉弱者，今自愈。</p><p>28、下利，脉数，有微热汗出，今自愈；设脉紧，为未解。</p><p>29、下利，脉数而渴者，今自愈。设不差，必清脓血，以有热故也。</p><p>30、下利，脉反弦，发热身汗者，自愈。</p><p>31、下利气者，当利其小便。</p><p>32、下利，寸脉反浮数，尺中自涩者，必清脓血。</p><p>33、下利清谷，不可攻其表，汗出必胀满。</p><p>34、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，必郁冒，汗出而解，病人必微热。所以然者，其面戴阳，下虚故也。</p><p>35、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。</p><p>36、下利，腹胀满，身体疼痛者，先温其里，乃攻其表。温里宜$f{四逆汤}，攻表宜$f{桂枝汤}。</p><p>37、下利，三部脉皆平，按之心下坚者，急下之，宜$f{大承气汤}。</p><p>38、下利，脉迟而滑者，实也。利未欲止，急下之，宜$f{大承气汤}。</p><p>39、下利，脉反滑者，当有所去，下乃愈，宜$f{大承气汤}。</p><p>40、下利已差，至其年月日时复发者，以病不尽故也，当下之，宜$f{大承气汤}。</p><p>41、下利，谵语者，有燥屎也，$f{小承气汤}主之。</p><p>42、下利，便脓血者，$f{桃花汤}主之。</p><p>43、热利下重者，$f{白头翁汤}主之。</p><p>44、下利后更烦，按之心下濡者，为虚烦也，$f{栀子豉汤}主之。</p><p>45、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。</p><p>46、下利，肺痛，$f{紫参汤}主之。</p><p>47、气利，$f{诃梨勒散}主之。</p><p>*、$q{《千金翼》}$f{小承气汤} 治大便不通，哕数谵语。</p><p>*、$q{《外台》}$f{黄芩人参汤} 治干呕下利。$a{玉函经云人参黄芩汤。本为黄芩汤，内容与伤寒论$f{黄芩汤}内容异，故改之。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":16,"no":17}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、夫呕家有痈脓，不可治呕，脓尽自愈。 2、先呕却渴者，此为欲解；先渴却呕者，为水停心下，此属饮家。呕家本渴，今反不渴者，以心下有支饮故也，此属支饮。 3、问曰：病人脉数，数为热，当消谷引食，而反吐者，何也？师曰：以发其汗，令阳微，膈气虚，脉乃数。数为客热，不能消谷，胃中虚冷故也。脉弦者，虚也，胃气无余，朝食暮吐，变为胃反。寒在于上，医反下之，今脉反弦，故名曰虚。 4、寸口脉微而数，微则无气，无气则荣虚，荣虚则血不足，血不足则胸中冷。 5、趺阳脉浮而涩，浮则为虚，涩则伤脾，脾伤则不磨，朝食暮吐，暮食朝吐，宿谷不化，名曰胃反。脉紧而涩，其病难治。 6、病人欲吐者，不可下之。 7、哕而腹满，视其前后，知何部不利，利之即愈。 8、呕而胸满者，$f{吴茱萸汤}主之。 9、干呕吐涎沫，头痛者，$f{吴茱萸汤}主之。 10、呕而肠鸣，心下痞者，$f{半夏泻心汤}主之。 11、干呕而利者，$f{黄芩加半夏生姜汤}主之。 12、诸呕吐，谷不得下者，$f{小半夏汤}主之。 13、呕吐而病在膈上，后思水者，解，急与之。思水者，$f{猪苓散}主之。 14、呕而脉弱，小便复利，身有微热，见厥者难治，$f{四逆汤}主之。 15、呕而发热者，$f{小柴胡汤}主之。 16、胃反呕吐者，$f{大半夏汤}主之。$a{$q{《千金》}云：治胃反不受食，食入即吐。$q{《外台》}云：治呕，心下痞硬者。} 17、食已即吐者，$f{大黄甘草汤}主之。$a{$q{《外台》}方：又治吐水。} 18、胃反，吐而渴欲饮水者，$f{茯苓泽泻汤}主之。 19、吐后，渴欲得水而贪饮者，$f{文蛤汤}主之，兼主微风，脉紧，头痛。 20、干呕，吐逆，吐涎沫，$f{半夏干姜散}主之。 21、病人胸中似喘不喘，似呕不呕，似哕不哕，彻心中愦愦然无奈者，$f{生姜半夏汤}主之。 22、干呕、哕，若手足厥者，$f{橘皮汤}主之。 23、哕逆者，$f{橘皮竹茹汤}主之。 24、夫六腑气绝于外者，手足寒，上气，脚缩；五脏气绝于内者，利不禁，下甚者，手足不仁。 25、下利，脉沉弦者，下重；脉大者，为未止；脉微弱数者，为欲自止，虽发热不死。 26、下利，手足厥冷，无脉者，灸之不温。若脉不还，反微喘者，死。少阴负趺阳者，为顺也。 27、下利，有微热而渴，脉弱者，今自愈。 28、下利，脉数，有微热汗出，今自愈；设脉紧，为未解。 29、下利，脉数而渴者，今自愈。设不差，必清脓血，以有热故也。 30、下利，脉反弦，发热身汗者，自愈。 31、下利气者，当利其小便。 32、下利，寸脉反浮数，尺中自涩者，必清脓血。 33、下利清谷，不可攻其表，汗出必胀满。 34、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，必郁冒，汗出而解，病人必微热。所以然者，其面戴阳，下虚故也。 35、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。 36、下利，腹胀满，身体疼痛者，先温其里，乃攻其表。温里宜$f{四逆汤}，攻表宜$f{桂枝汤}。 37、下利，三部脉皆平，按之心下坚者，急下之，宜$f{大承气汤}。 38、下利，脉迟而滑者，实也。利未欲止，急下之，宜$f{大承气汤}。 39、下利，脉反滑者，当有所去，下乃愈，宜$f{大承气汤}。 40、下利已差，至其年月日时复发者，以病不尽故也，当下之，宜$f{大承气汤}。 41、下利，谵语者，有燥屎也，$f{小承气汤}主之。 42、下利，便脓血者，$f{桃花汤}主之。 43、热利下重者，$f{白头翁汤}主之。 44、下利后更烦，按之心下濡者，为虚烦也，$f{栀子豉汤}主之。 45、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。 46、下利，肺痛，$f{紫参汤}主之。 47、气利，$f{诃梨勒散}主之。 *、$q{《千金翼》}$f{小承气汤} 治大便不通，哕数谵语。 *、$q{《外台》}$f{黄芩人参汤} 治干呕下利。$a{玉函经云人参黄芩汤。本为黄芩汤，内容与伤寒论$f{黄芩汤}内容异，故改之。}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PMhMk20Dhlf', 1, '{"title":"金匮要略18  疮痈肠痈浸淫","description":"<p>1、诸浮数脉，应当发热，而反洒淅恶寒，若有痛处，当发其痈。</p><p>2、师曰：诸痈肿，欲知有脓无脓，以手掩肿上，热者为有脓，不热者为无脓。</p><p>3、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为腹内有痈脓，$f{薏苡附子败酱散}主之。</p><p>4、肠痈者，少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒。其脉迟紧者，脓未成，可下之，当有血。脉洪数者，脓已成，不可下也。$f{大黄牡丹汤}主之。</p><p>5、问曰：寸口脉浮微而涩，然当亡血，若汗出，设不汗者云何？答曰：若身有疮，被刀斧所伤，亡血故也。</p><p>6、病金疮，$f{王不留行散}主之。</p><p>*、$f{排脓散}</p><p>*、$f{排脓汤}</p><p>7、浸淫疮，从口流向四肢者可治，从四肢流来入口者不可治。</p><p>8、浸淫疮，$f{黄连粉}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":17,"no":18}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、诸浮数脉，应当发热，而反洒淅恶寒，若有痛处，当发其痈。 2、师曰：诸痈肿，欲知有脓无脓，以手掩肿上，热者为有脓，不热者为无脓。 3、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为腹内有痈脓，$f{薏苡附子败酱散}主之。 4、肠痈者，少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒。其脉迟紧者，脓未成，可下之，当有血。脉洪数者，脓已成，不可下也。$f{大黄牡丹汤}主之。 5、问曰：寸口脉浮微而涩，然当亡血，若汗出，设不汗者云何？答曰：若身有疮，被刀斧所伤，亡血故也。 6、病金疮，$f{王不留行散}主之。 *、$f{排脓散} *、$f{排脓汤} 7、浸淫疮，从口流向四肢者可治，从四肢流来入口者不可治。 8、浸淫疮，$f{黄连粉}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iq3DOXRDnS0', 1, '{"title":"金匮要略19  趺蹶手指臂肿转筋阴狐疝蛔虫","description":"<p>1、师曰：病趺蹶，其人但能前，不能却，刺腨入二寸，此太阳经伤也。</p><p>2、病人常以手指臂肿动，此人身体瞤瞤者，$f{藜芦甘草汤}主之。</p><p>3、转筋之为病，其人臂脚直，脉上下行，微弦。转筋入腹者，$f{鸡屎白散}主之。</p><p>4、阴狐疝气者，偏有小大，时时上下，$f{蜘蛛散}主之。</p><p>5、问曰：病腹痛有虫，其脉何以别之？师曰：腹中痛，其脉当沉，若弦，反洪大，故有蛔虫。</p><p>6、蛔虫之为病，令人吐涎，心痛发作有时，毒药不止，$f{甘草粉蜜汤}主之。</p><p>7、蛔厥者，当吐蛔。今病者静而复时烦，此为脏寒，蛔上入膈，故烦。须臾复止，得食而呕，又烦者，蛔闻食臭出，其人当自吐蛔。</p><p>8、蛔厥者，$f{乌梅丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":18,"no":19}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、师曰：病趺蹶，其人但能前，不能却，刺腨入二寸，此太阳经伤也。 2、病人常以手指臂肿动，此人身体瞤瞤者，$f{藜芦甘草汤}主之。 3、转筋之为病，其人臂脚直，脉上下行，微弦。转筋入腹者，$f{鸡屎白散}主之。 4、阴狐疝气者，偏有小大，时时上下，$f{蜘蛛散}主之。 5、问曰：病腹痛有虫，其脉何以别之？师曰：腹中痛，其脉当沉，若弦，反洪大，故有蛔虫。 6、蛔虫之为病，令人吐涎，心痛发作有时，毒药不止，$f{甘草粉蜜汤}主之。 7、蛔厥者，当吐蛔。今病者静而复时烦，此为脏寒，蛔上入膈，故烦。须臾复止，得食而呕，又烦者，蛔闻食臭出，其人当自吐蛔。 8、蛔厥者，$f{乌梅丸}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8S0wDzCseKv', 1, '{"title":"金匮要略20  妇人妊娠病","description":"<p>1、师曰：妇人得平脉，阴脉小弱，其人渴，不能食，无寒热，名妊娠，$f{桂枝汤}主之。于法六十日当有此证，设有医治逆者，却一月加吐下者，则绝之。</p><p>2、妇人宿有癥病，经断未及三月，而得漏下不止，胎动在脐上者，为癥痼害。妊娠六月动者，前三月经水利时，胎也。下血者，后断三月衃也。所以血不止者，其症不去故也。当下其症，$f{桂枝茯苓丸}主之。</p><p>3、妇人怀娠六七月，脉弦发热，其胎愈胀，腹痛恶寒者，少腹如扇。所以然者，子脏开故也，当以$f{附子汤}温其脏。$a{方未见。}</p><p>4、师曰：妇人有漏下者，有半产后因续下血都不绝者，有妊娠下血者。假令妊娠腹中痛，为胞阻，$f{芎归胶艾汤}主之。</p><p>5、妇人怀妊，腹中㽲痛，$f{当归芍药散}主之。</p><p>6、妊娠呕吐不止，$f{干姜人参半夏丸}主之。</p><p>7、妊娠，小便难，饮食如故，$f{当归贝母苦参丸}主之。</p><p>8、妊娠有水气，身重，小便不利，洒淅恶寒，起即头眩，$f{葵子茯苓散}主之。</p><p>9、妇人妊娠，宜常服$f{当归散}主之。</p><p>10、妊娠养胎，$f{白术散}主之。</p><p>11、妇人伤胎，怀身腹满，不得小便，从腰以下重，如有水气状，怀身七月，太阴当养不养，此心气实，当刺泻劳宫及关元，小便微利则愈。$a{见$q{《玉函》}。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":19,"no":20}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '1、师曰：妇人得平脉，阴脉小弱，其人渴，不能食，无寒热，名妊娠，$f{桂枝汤}主之。于法六十日当有此证，设有医治逆者，却一月加吐下者，则绝之。 2、妇人宿有癥病，经断未及三月，而得漏下不止，胎动在脐上者，为癥痼害。妊娠六月动者，前三月经水利时，胎也。下血者，后断三月衃也。所以血不止者，其症不去故也。当下其症，$f{桂枝茯苓丸}主之。 3、妇人怀娠六七月，脉弦发热，其胎愈胀，腹痛恶寒者，少腹如扇。所以然者，子脏开故也，当以$f{附子汤}温其脏。$a{方未见。} 4、师曰：妇人有漏下者，有半产后因续下血都不绝者，有妊娠下血者。假令妊娠腹中痛，为胞阻，$f{芎归胶艾汤}主之。 5、妇人怀妊，腹中㽲痛，$f{当归芍药散}主之。 6、妊娠呕吐不止，$f{干姜人参半夏丸}主之。 7、妊娠，小便难，饮食如故，$f{当归贝母苦参丸}主之。 8、妊娠有水气，身重，小便不利，洒淅恶寒，起即头眩，$f{葵子茯苓散}主之。 9、妇人妊娠，宜常服$f{当归散}主之。 10、妊娠养胎，$f{白术散}主之。 11、妇人伤胎，怀身腹满，不得小便，从腰以下重，如有水气状，怀身七月，太阴当养不养，此心气实，当刺泻劳宫及关元，小便微利则愈。$a{见$q{《玉函》}。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5YLCsHs07RW', 1, '{"title":"金匮要略21  妇人产后病","description":"<p>1、问曰：新产妇人有三病，一者病痉，二者病郁冒，三者大便难，何谓也？师曰：新产血虚，多汗出，喜中风，故令病痉；亡血复汗，寒多，故令郁冒；亡津液，胃燥，故大便难。</p><p>2、产妇郁冒，其脉微弱，$a{呕}不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥而必冒，冒家欲解，必大汗出。以血虚下厥，孤阳上出，故头汗出。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复。大便坚，呕不能食，$f{小柴胡汤}主之。</p><p>3、病解能食，七八日更发热者，此为胃实，$f{大承气汤}主之。</p><p>4、产后腹中㽲痛，$f{当归生姜羊肉汤}主之，并治腹中寒疝，虚劳不足。</p><p>5、产后腹痛，烦满不得卧，$f{枳实芍药散}主之。</p><p>6、师曰：产妇腹痛，法当以$f{枳实芍药散}。假令不愈者，此为腹中有干血着脐下，宜$f{下瘀血汤}主之，亦主经水不利。</p><p>7、产后七八日，无太阳证，少腹坚痛，此恶露不尽。不大便，烦躁发热，切脉微实，再倍发热，日晡时烦躁者，不食，食则谵语，至夜即愈，宜$f{大承气汤}主之。热在里，结在膀胱也。</p><p>8、产后风，续之数十日不解，头微痛，恶寒，时时有热，心下闷，干呕汗出，虽久，阳旦证续在耳，可与$f{阳旦汤}。$a{即}$f{桂枝汤}$a{。}</p><p>9、产后中风发热，面正赤，喘而头痛，$f{竹叶汤}主之。</p><p>10、妇人乳中虚，烦乱呕逆，安中益气，$f{竹皮大丸}主之。</p><p>11、产后下利虚极，$f{白头翁加甘草阿胶汤}主之。</p><p>*、$q{附方《千金》}$f{三物黄芩汤} 治妇人在草蓐，自发露得风。四肢苦烦热，头痛者，与$f{小柴胡汤}。头不痛但烦者，此汤主之。</p><p>*、$q{《千金》}内补$f{当归建中汤} 治妇人产后虚羸不足，腹中刺痛不止，吸吸少气，或苦少腹中急，摩痛引腰者，不能食饮。产后一月，日得四五剂为善，令人强壮，宜。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":20,"no":21}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '1、问曰：新产妇人有三病，一者病痉，二者病郁冒，三者大便难，何谓也？师曰：新产血虚，多汗出，喜中风，故令病痉；亡血复汗，寒多，故令郁冒；亡津液，胃燥，故大便难。 2、产妇郁冒，其脉微弱，$a{呕}不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥而必冒，冒家欲解，必大汗出。以血虚下厥，孤阳上出，故头汗出。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复。大便坚，呕不能食，$f{小柴胡汤}主之。 3、病解能食，七八日更发热者，此为胃实，$f{大承气汤}主之。 4、产后腹中㽲痛，$f{当归生姜羊肉汤}主之，并治腹中寒疝，虚劳不足。 5、产后腹痛，烦满不得卧，$f{枳实芍药散}主之。 6、师曰：产妇腹痛，法当以$f{枳实芍药散}。假令不愈者，此为腹中有干血着脐下，宜$f{下瘀血汤}主之，亦主经水不利。 7、产后七八日，无太阳证，少腹坚痛，此恶露不尽。不大便，烦躁发热，切脉微实，再倍发热，日晡时烦躁者，不食，食则谵语，至夜即愈，宜$f{大承气汤}主之。热在里，结在膀胱也。 8、产后风，续之数十日不解，头微痛，恶寒，时时有热，心下闷，干呕汗出，虽久，阳旦证续在耳，可与$f{阳旦汤}。$a{即}$f{桂枝汤}$a{。} 9、产后中风发热，面正赤，喘而头痛，$f{竹叶汤}主之。 10、妇人乳中虚，烦乱呕逆，安中益气，$f{竹皮大丸}主之。 11、产后下利虚极，$f{白头翁加甘草阿胶汤}主之。 *、$q{附方《千金》}$f{三物黄芩汤} 治妇人在草蓐，自发露得风。四肢苦烦热，头痛者，与$f{小柴胡汤}。头不痛但烦者，此汤主之。 *、$q{《千金》}内补$f{当归建中汤} 治妇人产后虚羸不足，腹中刺痛不止，吸吸少气，或苦少腹中急，摩痛引腰者，不能食饮。产后一月，日得四五剂为善，令人强壮，宜。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Krxf3cMWLQC', 1, '{"title":"金匮要略22  妇人杂病","description":"<p>1、妇人中风，七八日续来寒热，发作有时，经水适断，此为热入血室，其血必结，故使如疟状，发作有时，$f{小柴胡汤}主之。</p><p>2、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，治之无犯胃气及上二焦，必自愈。</p><p>3、妇人中风，发热恶寒，经水适来，得七八日，热除脉迟，身凉和，胸胁满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而取之。</p><p>4、阳明病，下血谵语者，此为热入血室，但头汗出，当刺期门，随其实而泻之，濈然汗出者愈。</p><p>5、妇人咽中如有炙脔，$f{半夏厚朴汤}主之。</p><p>6、妇人脏躁，喜悲伤欲哭，象如神灵所作，数欠伸，$f{甘麦大枣汤}主之。</p><p>7、妇人吐涎沫，医反下之，心下即痞。当先治其吐涎沫，$f{小青龙汤}主之；涎沫止，乃治痞，$f{泻心汤}主之。</p><p>8、妇人之病，因虚、积冷、结气，为诸经水断绝，至有历年，血寒积结胞门，寒伤经络。凝坚在上，呕吐涎唾，久成肺痈，形体损分；在中盘结，绕脐寒疝，或两胁疼痛，与脏相连；或结热中，痛在关元。脉数无疮，肌若鱼鳞，时着男子，非止女身。在下未多，经候不匀。冷阴掣痛，少腹恶寒，或引腰脊，下根气街，气冲急痛，膝胫疼烦，奄忽眩冒，状如厥癫，或有忧惨，悲伤多嗔，此皆带下，非有鬼神，久则羸瘦，脉虚多寒。三十六病，千变万端，审脉阴阳，虚实紧弦，行其针药，治危得安，其虽同病，脉各异源，子当辨记，勿谓不然。</p><p>9、问曰：妇人年五十所，病下利数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？师曰：此病属带下。何以故？曾经半产，瘀血在少腹不去，何以知之？其证唇口干燥，故知之。当以$f{温经汤}主之。</p><p>10、带下经水不利，少腹满痛，经一月再见者，$f{土瓜根散}主之。</p><p>11、寸口脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，寒虚相抟，此名曰革，妇人则半产漏下，$f{旋覆花汤}主之。</p><p>12、妇人陷经，漏下，黑不解，$f{胶姜汤}主之。$a{臣亿等校诸本无胶姜汤方，想是前妊娠中}$f{芎归胶艾汤}$a{。}</p><p>13、妇人少腹满如敦状，小便微难而不渴，生后者，此为水与血并结在血室也，$f{大黄甘遂汤}主之。</p><p>14、妇人经水不利下，$f{抵当汤}主之。$a{亦治男子膀胱满急有瘀血者。}</p><p>15、妇人经水闭不利，脏坚癖不止，中有干血，下白物，$f{矾石丸}主之。</p><p>16、妇人六十二种风，及腹中血气刺痛，$f{红蓝花酒}主之。$a{疑非仲景方。}</p><p>17、妇人腹中诸疾痛，$f{当归芍药散}主之。</p><p>18、妇人腹中痛，$f{小建中汤}主之。</p><p>19、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？师曰：此名转胞，不得溺也。以胞系了戾，故致此病。但利小便则愈，宜$f{肾气丸}主之。</p><p>20、$f{蛇床子散}方，温阴中坐药。</p><p>21、少阴脉滑而数者，阴中即生疮，阴中蚀疮烂者，$f{狼牙汤}洗之。</p><p>22、胃气下泄，阴吹而正喧，此谷气之实也，$f{膏发煎}导之。</p><p>23、$f{小儿疳虫蚀齿}方 $a{疑非仲景方。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","section":21,"no":22}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '1、妇人中风，七八日续来寒热，发作有时，经水适断，此为热入血室，其血必结，故使如疟状，发作有时，$f{小柴胡汤}主之。 2、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，治之无犯胃气及上二焦，必自愈。 3、妇人中风，发热恶寒，经水适来，得七八日，热除脉迟，身凉和，胸胁满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而取之。 4、阳明病，下血谵语者，此为热入血室，但头汗出，当刺期门，随其实而泻之，濈然汗出者愈。 5、妇人咽中如有炙脔，$f{半夏厚朴汤}主之。 6、妇人脏躁，喜悲伤欲哭，象如神灵所作，数欠伸，$f{甘麦大枣汤}主之。 7、妇人吐涎沫，医反下之，心下即痞。当先治其吐涎沫，$f{小青龙汤}主之；涎沫止，乃治痞，$f{泻心汤}主之。 8、妇人之病，因虚、积冷、结气，为诸经水断绝，至有历年，血寒积结胞门，寒伤经络。凝坚在上，呕吐涎唾，久成肺痈，形体损分；在中盘结，绕脐寒疝，或两胁疼痛，与脏相连；或结热中，痛在关元。脉数无疮，肌若鱼鳞，时着男子，非止女身。在下未多，经候不匀。冷阴掣痛，少腹恶寒，或引腰脊，下根气街，气冲急痛，膝胫疼烦，奄忽眩冒，状如厥癫，或有忧惨，悲伤多嗔，此皆带下，非有鬼神，久则羸瘦，脉虚多寒。三十六病，千变万端，审脉阴阳，虚实紧弦，行其针药，治危得安，其虽同病，脉各异源，子当辨记，勿谓不然。 9、问曰：妇人年五十所，病下利数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？师曰：此病属带下。何以故？曾经半产，瘀血在少腹不去，何以知之？其证唇口干燥，故知之。当以$f{温经汤}主之。 10、带下经水不利，少腹满痛，经一月再见者，$f{土瓜根散}主之。 11、寸口脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，寒虚相抟，此名曰革，妇人则半产漏下，$f{旋覆花汤}主之。 12、妇人陷经，漏下，黑不解，$f{胶姜汤}主之。$a{臣亿等校诸本无胶姜汤方，想是前妊娠中}$f{芎归胶艾汤}$a{。} 13、妇人少腹满如敦状，小便微难而不渴，生后者，此为水与血并结在血室也，$f{大黄甘遂汤}主之。 14、妇人经水不利下，$f{抵当汤}主之。$a{亦治男子膀胱满急有瘀血者。} 15、妇人经水闭不利，脏坚癖不止，中有干血，下白物，$f{矾石丸}主之。 16、妇人六十二种风，及腹中血气刺痛，$f{红蓝花酒}主之。$a{疑非仲景方。} 17、妇人腹中诸疾痛，$f{当归芍药散}主之。 18、妇人腹中痛，$f{小建中汤}主之。 19、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？师曰：此名转胞，不得溺也。以胞系了戾，故致此病。但利小便则愈，宜$f{肾气丸}主之。 20、$f{蛇床子散}方，温阴中坐药。 21、少阴脉滑而数者，阴中即生疮，阴中蚀疮烂者，$f{狼牙汤}洗之。 22、胃气下泄，阴吹而正喧，此谷气之实也，$f{膏发煎}导之。 23、$f{小儿疳虫蚀齿}方 $a{疑非仲景方。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5LShm6O3ONu', 4, '{"title":"第2000000条・金匮要略1  脏腑经络先后病","description":"<p>1、问曰：上工治未病，何也？师曰：夫治未病者，见肝之病，知肝传脾，当先实脾。四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，$a{俞桥本，赵开美本，更有心火气盛四字。}则伤肺；肺被伤，则金气不行；金气不行，则肝气盛。$a{俞本有故实脾三字，}则肝自愈。此治肝补脾之要妙也。肝虚则用此法，实则不在用之。经曰：虚虚实实，补不足，损有余。是其义也。余脏准此。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、问曰：上工治未病，何也？师曰：夫治未病者，见肝之病，知肝传脾，当先实脾。四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。夫肝之病，补用酸，助用焦苦，益用甘味之药调之。酸入肝，焦苦入心，甘入脾。脾能伤肾，肾气微弱，则水不行；水不行，则心火气盛，$a{俞桥本，赵开美本，更有心火气盛四字。}则伤肺；肺被伤，则金气不行；金气不行，则肝气盛。$a{俞本有故实脾三字，}则肝自愈。此治肝补脾之要妙也。肝虚则用此法，实则不在用之。经曰：虚虚实实，补不足，损有余。是其义也。余脏准此。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HJLHYQliNhf', 4, '{"title":"第2000001条・金匮要略1  脏腑经络先后病","description":"<p>2、夫人秉五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和，客气邪风，中人多死。千般疢难，不越三条：一者，经络受邪，入脏腑，为内所因也；二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也；三者，房室、金刃、虫兽所伤，以此详之，病由都尽。若人能养慎，不令邪风干忤经络，适中经络，未流传脏腑，即医治之。四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、夫人秉五常，因风气而生长，风气虽能生万物，亦能害万物，如水能浮舟，亦能覆舟。若五脏元真通畅，人即安和，客气邪风，中人多死。千般疢难，不越三条：一者，经络受邪，入脏腑，为内所因也；二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也；三者，房室、金刃、虫兽所伤，以此详之，病由都尽。若人能养慎，不令邪风干忤经络，适中经络，未流传脏腑，即医治之。四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遗形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处，为血气所注；理者，是皮肤脏腑之纹理也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1vFyhBkuQ50', 4, '{"title":"第2000002条・金匮要略1  脏腑经络先后病","description":"<p>3、问曰：病人有气色见于面部，愿闻其说。师曰：鼻头色青，腹中痛，苦冷者死。$a{一云腹中冷，苦痛者死。}鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤，非时者死。其目正圆者，痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、问曰：病人有气色见于面部，愿闻其说。师曰：鼻头色青，腹中痛，苦冷者死。$a{一云腹中冷，苦痛者死。}鼻头色微黑者，有水气；色黄者，胸上有寒；色白者，亡血也。设微赤，非时者死。其目正圆者，痉，不治。又色青为痛，色黑为劳，色赤为风，色黄者便难，色鲜明者有留饮。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3hS2pfz9b77', 4, '{"title":"第2000003条・金匮要略1  脏腑经络先后病","description":"<p>4、师曰：病人语声寂然，喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病$a{一作痛}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '4、师曰：病人语声寂然，喜惊呼者，骨节间病；语声喑喑然不彻者，心膈间病；语声啾啾然细而长者，头中病$a{一作痛}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IW5oEwPHi7H', 4, '{"title":"第2000004条・金匮要略1  脏腑经络先后病","description":"<p>5、师曰：息摇肩者，心中坚；息引胸中上气者，咳；息张口短气者，肺痿唾沫。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '5、师曰：息摇肩者，心中坚；息引胸中上气者，咳；息张口短气者，肺痿唾沫。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vf8KVAilKEF', 4, '{"title":"第2000005条・金匮要略1  脏腑经络先后病","description":"<p>6、师曰：吸而微数，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促；在下焦者，其吸远，此皆难治。呼吸动摇振振者，不治。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '6、师曰：吸而微数，其病在中焦，实也，当下之即愈，虚者不治。在上焦者，其吸促；在下焦者，其吸远，此皆难治。呼吸动摇振振者，不治。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vmuQ3BMTLYJ', 4, '{"title":"第2000006条・金匮要略1  脏腑经络先后病","description":"<p>7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反色白，非其时色脉，皆当病。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '7、师曰：寸口脉动者，因其旺时而动，假令肝旺色青，四时各随其色。肝色青而反色白，非其时色脉，皆当病。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ldEjZx7Oo4L', 4, '{"title":"第2000007条・金匮要略1  脏腑经络先后病","description":"<p>8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起。少阳之时，阳始生，天得温和。以未得甲子，天因温和，此为未至而至也；以得甲子而天未温和，$a{此}为至而不至也；以得甲子而天大寒不解，此为至而不去也；以得甲子而天温如盛夏五六月时，此为至而太过也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '8、问曰：有未至而至，有至而不至，有至而不去，有至而太过，何谓也？师曰：冬至之后，甲子夜半少阳起。少阳之时，阳始生，天得温和。以未得甲子，天因温和，此为未至而至也；以得甲子而天未温和，$a{此}为至而不至也；以得甲子而天大寒不解，此为至而不去也；以得甲子而天温如盛夏五六月时，此为至而太过也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0chNgukSoqv', 4, '{"title":"第2000008条・金匮要略1  脏腑经络先后病","description":"<p>9、师曰：病人脉浮者在前，其病在表；浮者在后，其病在里。腰痛背强不能行，必短气而极也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '9、师曰：病人脉浮者在前，其病在表；浮者在后，其病在里。腰痛背强不能行，必短气而极也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s59EOnvOq8T', 4, '{"title":"第2000009条・金匮要略1  脏腑经络先后病","description":"<p>10、问曰：经云：厥阳独行，何谓也？师曰：此为有阳无阴，故称厥阳。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '10、问曰：经云：厥阳独行，何谓也？师曰：此为有阳无阴，故称厥阳。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mj4B0NlrECz', 4, '{"title":"第2000010条・金匮要略1  脏腑经络先后病","description":"<p>11、问曰：寸脉沉大而滑，沉则为实，滑则为气。实气相抟，血气入脏即死，入腑即愈，此为卒厥。何谓也？师曰：唇口青，身冷，为入脏即死；如身和，汗自出，为入腑即愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '11、问曰：寸脉沉大而滑，沉则为实，滑则为气。实气相抟，血气入脏即死，入腑即愈，此为卒厥。何谓也？师曰：唇口青，身冷，为入脏即死；如身和，汗自出，为入腑即愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mfKErJl2ZSY', 4, '{"title":"第2000011条・金匮要略1  脏腑经络先后病","description":"<p>12、问曰：脉脱入脏即死，入腑即愈，何谓也？师曰：非为一病，百病皆然。譬如浸淫疮，从口起流向四肢者，可治；从四肢流来入口者，不可治；病在外者，可治；入里者，即死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '12、问曰：脉脱入脏即死，入腑即愈，何谓也？师曰：非为一病，百病皆然。譬如浸淫疮，从口起流向四肢者，可治；从四肢流来入口者，不可治；病在外者，可治；入里者，即死。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AQiYiKalXM6', 4, '{"title":"第2000012条・金匮要略1  脏腑经络先后病","description":"<p>13、问曰：阳病十八，何谓也？师曰：头痛，项、腰、脊、臂、脚掣痛。阴病十八，何谓也？师曰：咳，上气，喘，哕，咽，肠鸣，胀满，心痛，拘急。五脏病各有十八，合为九十病。人又有六微，微有十八病，合为一百八病。五劳七伤六极，妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里。穀饪之邪，从口入者，宿食也。五邪中人，各有法度：风中于前，寒中于暮，湿伤于下，雾伤于上，风令脉浮，寒令脉急，雾伤皮腠，湿流关节，食伤脾胃，极寒伤经，极热伤络。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '13、问曰：阳病十八，何谓也？师曰：头痛，项、腰、脊、臂、脚掣痛。阴病十八，何谓也？师曰：咳，上气，喘，哕，咽，肠鸣，胀满，心痛，拘急。五脏病各有十八，合为九十病。人又有六微，微有十八病，合为一百八病。五劳七伤六极，妇人三十六病，不在其中。清邪居上，浊邪居下，大邪中表，小邪中里。穀饪之邪，从口入者，宿食也。五邪中人，各有法度：风中于前，寒中于暮，湿伤于下，雾伤于上，风令脉浮，寒令脉急，雾伤皮腠，湿流关节，食伤脾胃，极寒伤经，极热伤络。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kfS8OsBs4bE', 4, '{"title":"第2000013条・金匮要略1  脏腑经络先后病","description":"<p>14、问曰：病有急当救里、救表者，何谓也？师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身体疼痛，清便自调者，急当救表也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '14、问曰：病有急当救里、救表者，何谓也？师曰：病，医下之，续得下利清谷不止，身体疼痛者，急当救里；后身体疼痛，清便自调者，急当救表也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SX9p5rBnj6K', 4, '{"title":"第2000014条・金匮要略1  脏腑经络先后病","description":"<p>15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2BR8hac3SwF', 4, '{"title":"第2000015条・金匮要略1  脏腑经络先后病","description":"<p>16、师曰：五脏病各有所得者愈，五脏病各有所恶，各随其所不喜者为病。病者素不应食，而反暴思之，必发热也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '16、师曰：五脏病各有所得者愈，五脏病各有所恶，各随其所不喜者为病。病者素不应食，而反暴思之，必发热也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vVm4QzV75uJ', 4, '{"title":"第2000016条・金匮要略1  脏腑经络先后病","description":"<p>17、夫诸病在脏欲攻之，当随其所得而攻之，如渴者，与$f{猪苓汤}，余皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2000016,"note":"","videoMemo":"","fangList":["猪苓汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '17、夫诸病在脏欲攻之，当随其所得而攻之，如渴者，与$f{猪苓汤}，余皆仿此。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '9lSFOt9wtL7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7YrTa2YGZAB', 4, '{"title":"第2001000条・金匮要略2  痉湿暍","description":"<p>1、太阳病，发热无汗，反恶寒者，名曰刚痉。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、太阳病，发热无汗，反恶寒者，名曰刚痉。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LjUXEdwABNU', 4, '{"title":"第2001001条・金匮要略2  痉湿暍","description":"<p>2、太阳病，发热汗出而不恶寒，名曰柔痉。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、太阳病，发热汗出而不恶寒，名曰柔痉。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LP3rP0XVOWT', 4, '{"title":"第2001002条・金匮要略2  痉湿暍","description":"<p>3、太阳病，发热，脉沉而细者，名曰痉，为难治。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、太阳病，发热，脉沉而细者，名曰痉，为难治。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('629FJVzg8Nj', 4, '{"title":"第2001003条・金匮要略2  痉湿暍","description":"<p>4、太阳病，发汗太多，因致痉。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '4、太阳病，发汗太多，因致痉。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zMNt45WcnMD', 4, '{"title":"第2001004条・金匮要略2  痉湿暍","description":"<p>5、夫风病，下之则痉，复发汗，必拘急。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '5、夫风病，下之则痉，复发汗，必拘急。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BhZ6pisrL3h', 4, '{"title":"第2001005条・金匮要略2  痉湿暍","description":"<p>6、疮家虽身疼痛，不可发汗，汗出则痉。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '6、疮家虽身疼痛，不可发汗，汗出则痉。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kGTbplpeicP', 4, '{"title":"第2001006条・金匮要略2  痉湿暍","description":"<p>7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗者，寒湿相得，其表益虚，即恶寒甚。发其汗已，其脉如蛇。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗者，寒湿相得，其表益虚，即恶寒甚。发其汗已，其脉如蛇。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TlaYPLJM50W', 4, '{"title":"第2001007条・金匮要略2  痉湿暍","description":"<p>8、暴腹胀大者，为欲解，脉如故，反伏弦者，痉。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '8、暴腹胀大者，为欲解，脉如故，反伏弦者，痉。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fSqU2n0wUcL', 4, '{"title":"第2001008条・金匮要略2  痉湿暍","description":"<p>9、夫痉脉，按之紧如弦，直上下行。$a{一作筑筑而弦。《脉经》云：痉家其脉伏坚，直上下。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '9、夫痉脉，按之紧如弦，直上下行。$a{一作筑筑而弦。《脉经》云：痉家其脉伏坚，直上下。}', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DCnklvyy8ym', 4, '{"title":"第2001009条・金匮要略2  痉湿暍","description":"<p>10、痉病有灸疮，难治。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '10、痉病有灸疮，难治。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xVeYpO4i8QY', 4, '{"title":"第2001010条・金匮要略2  痉湿暍","description":"<p>11、太阳病，其证备，身体强几几，然脉反沉迟，此为痉，$f{栝楼桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001010,"note":"","videoMemo":"","fangList":["栝楼桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '11、太阳病，其证备，身体强几几，然脉反沉迟，此为痉，$f{栝楼桂枝汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OOHhNWINKyO', 4, '{"title":"第2001011条・金匮要略2  痉湿暍","description":"<p>12、太阳病，无汗而小便反少，气上冲胸，口噤不得语，欲作刚痉，$f{葛根汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001011,"note":"","videoMemo":"","fangList":["葛根汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '12、太阳病，无汗而小便反少，气上冲胸，口噤不得语，欲作刚痉，$f{葛根汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('REdBNGfBJ0G', 4, '{"title":"第2001012条・金匮要略2  痉湿暍","description":"<p>13、痉为病$a{，一本痉字上有刚字}，胸满口噤，卧不着席，脚挛急，必齘齿，可与$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001012,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '13、痉为病$a{，一本痉字上有刚字}，胸满口噤，卧不着席，脚挛急，必齘齿，可与$f{大承气汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fPp6IlEQ559', 4, '{"title":"第2001013条・金匮要略2  痉湿暍","description":"<p>14、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹。$a{《玉函》云中湿。}湿痹之候，小便不利，大便反快，但当利其小便。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '14、太阳病，关节疼痛而烦，脉沉而细者，此名湿痹。$a{《玉函》云中湿。}湿痹之候，小便不利，大便反快，但当利其小便。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kZNYB65S7eP', 4, '{"title":"第2001014条・金匮要略2  痉湿暍","description":"<p>15、湿家之为病，一身尽疼$a{一云疼烦}，发热，身色如熏黄也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '15、湿家之为病，一身尽疼$a{一云疼烦}，发热，身色如熏黄也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SbL5D4Qrx72', 4, '{"title":"第2001015条・金匮要略2  痉湿暍","description":"<p>16、湿家其人但头汗出，背强，欲得被覆向火。若下之早则哕，或胸满，小便不利$a{一云利}，舌上如胎者，以丹田有热，胸上有寒，渴欲得饮而不能饮，则口燥烦也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '16、湿家其人但头汗出，背强，欲得被覆向火。若下之早则哕，或胸满，小便不利$a{一云利}，舌上如胎者，以丹田有热，胸上有寒，渴欲得饮而不能饮，则口燥烦也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qhdCrxAvMHI', 4, '{"title":"第2001016条・金匮要略2  痉湿暍","description":"<p>17、湿家下之，额上汗出，微喘，小便利$a{一云不利}者，死；若下利不止者亦死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '17、湿家下之，额上汗出，微喘，小便利$a{一云不利}者，死；若下利不止者亦死。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l5T6GGkbYo6', 4, '{"title":"第2001017条・金匮要略2  痉湿暍","description":"<p>18、风湿相抟，一身尽疼痛，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者，何也？盖发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者发其汗，但微微似欲出汗者，风湿俱去也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '18、风湿相抟，一身尽疼痛，法当汗出而解，值天阴雨不止，医云此可发汗，汗之病不愈者，何也？盖发其汗，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者发其汗，但微微似欲出汗者，风湿俱去也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PxCTSW4Q01H', 4, '{"title":"第2001018条・金匮要略2  痉湿暍","description":"<p>19、湿家病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故鼻塞，内药鼻中则愈。$a{《脉经》云：病人喘，而无湿家病以下至而喘十一字。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '19、湿家病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故鼻塞，内药鼻中则愈。$a{《脉经》云：病人喘，而无湿家病以下至而喘十一字。}', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iAbEs6aiLZi', 4, '{"title":"第2001019条・金匮要略2  痉湿暍","description":"<p>20、湿家身烦疼，可与$f{麻黄加术汤}，发其汗为宜，慎不可以火攻之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001019,"note":"","videoMemo":"","fangList":["麻黄加术汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '20、湿家身烦疼，可与$f{麻黄加术汤}，发其汗为宜，慎不可以火攻之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('21DQwJ7P029', 4, '{"title":"第2001020条・金匮要略2  痉湿暍","description":"<p>21、病者一身尽疼，发热，日晡所剧者，名风湿。此病伤于汗出当风，或久伤取冷所致也。可与$f{麻黄杏仁薏苡甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001020,"note":"","videoMemo":"","fangList":["麻黄杏仁薏苡甘草汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '21、病者一身尽疼，发热，日晡所剧者，名风湿。此病伤于汗出当风，或久伤取冷所致也。可与$f{麻黄杏仁薏苡甘草汤}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3k7gZUYIrvn', 4, '{"title":"第2001021条・金匮要略2  痉湿暍","description":"<p>22、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001021,"note":"","videoMemo":"","fangList":["防己黄芪汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '22、风湿，脉浮，身重，汗出，恶风者，$f{防己黄芪汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lj0KOFWaLKR', 4, '{"title":"第2001022条・金匮要略2  痉湿暍","description":"<p>23、伤寒八九日，风湿相抟，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{去桂加白术汤}主之。$a{金匮此处附方为$f{白术附子汤}}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001022,"note":"","videoMemo":"","fangList":["桂枝附子汤","去桂加白术汤","白术附子汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '23、伤寒八九日，风湿相抟，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利者，$f{去桂加白术汤}主之。$a{金匮此处附方为$f{白术附子汤}}', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XSJKo5bk363', 4, '{"title":"第2001023条・金匮要略2  痉湿暍","description":"<p>24、风湿相抟，骨节疼烦，掣痛不得屈伸，近之则痛剧，汗出短气，小便不利，恶风不欲去衣，或身微肿者，$f{甘草附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001023,"note":"","videoMemo":"","fangList":["甘草附子汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '24、风湿相抟，骨节疼烦，掣痛不得屈伸，近之则痛剧，汗出短气，小便不利，恶风不欲去衣，或身微肿者，$f{甘草附子汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RcEt5pVfVRN', 4, '{"title":"第2001024条・金匮要略2  痉湿暍","description":"<p>25、太阳中暍，发热恶寒，身重而疼痛，其脉弦细芤迟。小便已，洒洒然毛耸，手足逆冷，小有劳，身即热，口开，前板齿燥。若发其汗，则其恶寒甚；加温针，则发热甚；数下之，则淋甚。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '25、太阳中暍，发热恶寒，身重而疼痛，其脉弦细芤迟。小便已，洒洒然毛耸，手足逆冷，小有劳，身即热，口开，前板齿燥。若发其汗，则其恶寒甚；加温针，则发热甚；数下之，则淋甚。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('udL3NGYDaeh', 4, '{"title":"第2001025条・金匮要略2  痉湿暍","description":"<p>26、太阳中热者，暍是也。汗出恶寒，身热而渴，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001025,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '26、太阳中热者，暍是也。汗出恶寒，身热而渴，$f{白虎加人参汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G4ybXxfg3li', 4, '{"title":"第2001026条・金匮要略2  痉湿暍","description":"<p>27、太阳中暍，身热疼重而脉微弱，此以夏月伤冷水，水行皮中所致也。$f{一物瓜蒂汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2001026,"note":"","videoMemo":"","fangList":["一物瓜蒂汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '27、太阳中暍，身热疼重而脉微弱，此以夏月伤冷水，水行皮中所致也。$f{一物瓜蒂汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0lHavJPW2wc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3Cxe081WkSm', 4, '{"title":"第2002000条・金匮要略3  百合狐惑阴阳毒","description":"<p>1、论曰：百合病者，百脉一宗，悉致其病也。意欲食复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不用闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅然者，四十日愈；若溺快然，但头眩者，二十日愈。其证或未病而预见，或病四五日而出，或病二十日，或一月微见者，各随证治之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、论曰：百合病者，百脉一宗，悉致其病也。意欲食复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不用闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅然者，四十日愈；若溺快然，但头眩者，二十日愈。其证或未病而预见，或病四五日而出，或病二十日，或一月微见者，各随证治之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qfMKObxTjam', 4, '{"title":"第2002001条・金匮要略3  百合狐惑阴阳毒","description":"<p>2、百合病发汗后者，$f{百合知母汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002001,"note":"","videoMemo":"","fangList":["百合知母汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、百合病发汗后者，$f{百合知母汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
