INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('go77wKYn8Y2', 4, '{"title":"第2002005条・金匮要略3  百合狐惑阴阳毒","description":"<p>6、百合病一月不解，变成渴者，$f{百合洗}方主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002005,"note":"","videoMemo":"","fangList":["百合洗"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '6、百合病一月不解，变成渴者，$f{百合洗}方主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
