INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5mPINbx9aF1', 4, '{"title":"第2002007条・金匮要略3  百合狐惑阴阳毒","description":"<p>8、百合病变发热者，$a{一作发寒热。}$f{百合滑石散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002007,"note":"","videoMemo":"","fangList":["百合滑石散"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '8、百合病变发热者，$a{一作发寒热。}$f{百合滑石散}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wr7V604eKot', 4, '{"title":"第2002008条・金匮要略3  百合狐惑阴阳毒","description":"<p>9、百合病见于阴者，以阳法救之；见于阳者，以阴法救之。见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '9、百合病见于阴者，以阳法救之；见于阳者，以阴法救之。见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T3xp3yF3OWq', 4, '{"title":"第2002009条・金匮要略3  百合狐惑阴阳毒","description":"<p>10、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐。不欲饮食，恶闻食臭，其面目乍赤、乍黑、乍白。蚀于上部则声喝$a{一作嗄}，$f{甘草泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002009,"note":"","videoMemo":"","fangList":["甘草泻心汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '10、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐。不欲饮食，恶闻食臭，其面目乍赤、乍黑、乍白。蚀于上部则声喝$a{一作嗄}，$f{甘草泻心汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ifGCJYBwNH1', 4, '{"title":"第2002010条・金匮要略3  百合狐惑阴阳毒","description":"<p>11、蚀于下部则咽干，$f{苦参汤}洗之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002010,"note":"","videoMemo":"","fangList":["苦参汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '11、蚀于下部则咽干，$f{苦参汤}洗之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hd6WyGiuW36', 4, '{"title":"第2002011条・金匮要略3  百合狐惑阴阳毒","description":"<p>12、蚀于肛者，$f{雄黄}熏之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002011,"note":"","videoMemo":"","fangList":["雄黄"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '12、蚀于肛者，$f{雄黄}熏之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j8OQzNGbiyi', 4, '{"title":"第2002012条・金匮要略3  百合狐惑阴阳毒","description":"<p>13、病者脉数，无热，微烦，默默但欲卧，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦$a{一本此有黄字}黑，若能食者，脓已成也。$f{赤豆当归散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002012,"note":"","videoMemo":"","fangList":["赤豆当归散"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '13、病者脉数，无热，微烦，默默但欲卧，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦$a{一本此有黄字}黑，若能食者，脓已成也。$f{赤豆当归散}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n3pW6W929RX', 4, '{"title":"第2002013条・金匮要略3  百合狐惑阴阳毒","description":"<p>14、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血。五日可治，七日不可治。$f{升麻鳖甲汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002013,"note":"","videoMemo":"","fangList":["升麻鳖甲汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '14、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血。五日可治，七日不可治。$f{升麻鳖甲汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HQRXBXt0DFB', 4, '{"title":"第2002014条・金匮要略3  百合狐惑阴阳毒","description":"<p>15、阴毒之为病，面目青，身痛如被杖，咽喉痛。五日可治，七日不可治，$f{升麻鳖甲汤}去$u{雄黄}、$u{蜀椒}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2002014,"note":"","videoMemo":"","fangList":["升麻鳖甲汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '15、阴毒之为病，面目青，身痛如被杖，咽喉痛。五日可治，七日不可治，$f{升麻鳖甲汤}去$u{雄黄}、$u{蜀椒}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'kQ4TW5Ncvxf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7FFp3Hsk65g', 4, '{"title":"第2003000条・金匮要略4  疟病","description":"<p>1、师曰：疟脉自弦，弦数者多热，弦迟者多寒。弦小紧者，下之差，弦迟者，可温之；弦紧者，可发汗，针灸也；浮大者，可吐之；弦数者，风发也，以饮食消息止之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2003000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、师曰：疟脉自弦，弦数者多热，弦迟者多寒。弦小紧者，下之差，弦迟者，可温之；弦紧者，可发汗，针灸也；浮大者，可吐之；弦数者，风发也，以饮食消息止之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'ti5h73khf2s');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zg5GrHOaj8q', 4, '{"title":"第2003001条・金匮要略4  疟病","description":"<p>2、病疟，以月一日发，当以十五日愈；设不差，当月尽解；如其不差，当云何？师曰：此结为癥瘕，名曰疟母，急治之，宜$f{鳖甲煎丸}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2003001,"note":"","videoMemo":"","fangList":["鳖甲煎丸"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、病疟，以月一日发，当以十五日愈；设不差，当月尽解；如其不差，当云何？师曰：此结为癥瘕，名曰疟母，急治之，宜$f{鳖甲煎丸}。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'ti5h73khf2s');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X1uJZSRa2QF', 4, '{"title":"第2003002条・金匮要略4  疟病","description":"<p>3、师曰：阴气孤绝，阳气独发，则热而少气烦冤，手足热而欲呕，名曰瘅疟。若但热不寒者，邪气内藏于心，外舍分肉之间，令人消铄脱肉。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2003002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、师曰：阴气孤绝，阳气独发，则热而少气烦冤，手足热而欲呕，名曰瘅疟。若但热不寒者，邪气内藏于心，外舍分肉之间，令人消铄脱肉。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'ti5h73khf2s');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f7ZlmLSBd4u', 4, '{"title":"第2003003条・金匮要略4  疟病","description":"<p>4、温疟者，其脉如平，身无寒但热，骨节疼烦，时呕，$f{白虎加桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2003003,"note":"","videoMemo":"","fangList":["白虎加桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '4、温疟者，其脉如平，身无寒但热，骨节疼烦，时呕，$f{白虎加桂枝汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'ti5h73khf2s');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e1w6pH8UjaG', 4, '{"title":"第2003004条・金匮要略4  疟病","description":"<p>5、疟多寒者，名曰牡疟，$f{蜀漆散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2003004,"note":"","videoMemo":"","fangList":["蜀漆散"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '5、疟多寒者，名曰牡疟，$f{蜀漆散}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'ti5h73khf2s');
