INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ktboD7giMj1', 4, '{"title":"第2003006条・金匮要略4  疟病","description":"<p>*、$q{附《外台秘要》}$f{柴胡去半夏加栝楼汤} 治疟病发渴者，亦治劳疟。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2003006,"note":"","videoMemo":"","fangList":["柴胡去半夏加栝楼汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '*、$q{附《外台秘要》}$f{柴胡去半夏加栝楼汤} 治疟病发渴者，亦治劳疟。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'ti5h73khf2s');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UUlWyNfOl9e', 4, '{"title":"第2003007条・金匮要略4  疟病","description":"<p>*、$q{附《外台秘要》}$f{柴胡桂枝干姜汤} 治疟寒多，微有热，或但寒不热。服一剂如神。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2003007,"note":"","videoMemo":"","fangList":["柴胡桂枝干姜汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '*、$q{附《外台秘要》}$f{柴胡桂枝干姜汤} 治疟寒多，微有热，或但寒不热。服一剂如神。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'ti5h73khf2s');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p2L0NlmqV0X', 4, '{"title":"第2004000条・金匮要略5  中风历节","description":"<p>1、夫风之为病，当半身不遂；或但臂不遂者，此为痹。脉微而数，中风使然。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、夫风之为病，当半身不遂；或但臂不遂者，此为痹。脉微而数，中风使然。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2jKluty7VcJ', 4, '{"title":"第2004001条・金匮要略5  中风历节","description":"<p>2、寸口脉浮而紧，紧则为寒，浮则为虚，寒虚相抟，邪在皮肤。浮者血虚，络脉空虚，贼邪不泻，或左或右；邪气反缓，正气即急，正气引邪，㖞僻不遂。邪在于络，肌肤不仁；邪在于经，即重不胜；邪入于腑，即不识人；邪入于脏，舌即难言，口吐涎。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、寸口脉浮而紧，紧则为寒，浮则为虚，寒虚相抟，邪在皮肤。浮者血虚，络脉空虚，贼邪不泻，或左或右；邪气反缓，正气即急，正气引邪，㖞僻不遂。邪在于络，肌肤不仁；邪在于经，即重不胜；邪入于腑，即不识人；邪入于脏，舌即难言，口吐涎。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ps37LG8Aoxp', 4, '{"title":"第2004002条・金匮要略5  中风历节","description":"<p>*、$f{侯氏黑散} 治大风，四肢烦重，心中恶寒不足者。$q{《外台》}治风癫。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004002,"note":"","videoMemo":"","fangList":["侯氏黑散"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '*、$f{侯氏黑散} 治大风，四肢烦重，心中恶寒不足者。$q{《外台》}治风癫。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fQEPppFjxx3', 4, '{"title":"第2004003条・金匮要略5  中风历节","description":"<p>3、寸口脉迟而缓，迟则为寒，缓则为虚。营缓则为亡血，卫缓则为中风。邪气中经，则身痒而瘾疹；心气不足，邪气入中，则胸满而短气。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、寸口脉迟而缓，迟则为寒，缓则为虚。营缓则为亡血，卫缓则为中风。邪气中经，则身痒而瘾疹；心气不足，邪气入中，则胸满而短气。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('12wUTD5zOpW', 4, '{"title":"第2004004条・金匮要略5  中风历节","description":"<p>*、$f{风引汤} 除热瘫癎。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004004,"note":"","videoMemo":"","fangList":["风引汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '*、$f{风引汤} 除热瘫癎。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
