INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JKFZV6VpA8M', 4, '{"title":"第2004007条・金匮要略5  中风历节","description":"<p>4、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节黄汗出，故曰历节。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '4、寸口脉沉而弱，沉即主骨，弱即主筋，沉即为肾，弱即为肝，汗出入水中，如水伤心，历节黄汗出，故曰历节。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
