INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2cpMecMRBgT', 4, '{"title":"第2004009条・金匮要略5  中风历节","description":"<p>6、少阴脉浮而弱，弱则血不足，浮则为风，风血相抟，即疼痛如掣。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '6、少阴脉浮而弱，弱则血不足，浮则为风，风血相抟，即疼痛如掣。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xsw0XiRUOm5', 4, '{"title":"第2004010条・金匮要略5  中风历节","description":"<p>7、盛人脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '7、盛人脉涩小，短气，自汗出，历节疼，不可屈伸，此皆饮酒汗出当风所致。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
