INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IqtCVXN8bHZ', 4, '{"title":"第2004012条・金匮要略5  中风历节","description":"<p>9、味酸则伤筋，筋伤则缓，名曰泄；咸则伤骨，骨伤则痿，名曰枯。枯泄相抟，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无所御，四属断绝，身体羸瘦。独足肿大，黄汗出，胫冷。假令发热，便为历节也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2004012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '9、味酸则伤筋，筋伤则缓，名曰泄；咸则伤骨，骨伤则痿，名曰枯。枯泄相抟，名曰断泄。荣气不通，卫不独行，荣卫俱微，三焦无所御，四属断绝，身体羸瘦。独足肿大，黄汗出，胫冷。假令发热，便为历节也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'zwUX1LcqUfN');
