INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vA42T0Y7XS', 4, '{"title":"第2005002条・金匮要略6  血痹虚劳","description":"<p>3、夫男子平人，脉大为劳，极虚亦为劳。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2005002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、夫男子平人，脉大为劳，极虚亦为劳。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'QMamiO7b1M5');
