INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7TYgcRBLu6S', 4, '{"title":"第2005010条・金匮要略6  血痹虚劳","description":"<p>10、人年五六十，其病脉大者，痹侠背行，若$a{宋本、赵本作苦}肠鸣，马刀侠瘿者，皆为劳得之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2005010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '10、人年五六十，其病脉大者，痹侠背行，若$a{宋本、赵本作苦}肠鸣，马刀侠瘿者，皆为劳得之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'QMamiO7b1M5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U1BUNvsJlhc', 4, '{"title":"第2005011条・金匮要略6  血痹虚劳","description":"<p>11、脉沉小迟，名脱气。其人疾行则喘喝，手足逆寒，腹满，甚则溏泄，食不消化也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2005011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '11、脉沉小迟，名脱气。其人疾行则喘喝，手足逆寒，腹满，甚则溏泄，食不消化也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'QMamiO7b1M5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GlTuSA3eE5L', 4, '{"title":"第2005012条・金匮要略6  血痹虚劳","description":"<p>12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，虚寒相抟，此名为革。妇人则半产漏下，男子则亡血失精。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2005012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，虚寒相抟，此名为革。妇人则半产漏下，男子则亡血失精。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'QMamiO7b1M5');
