INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w1HHTwXZND2', 4, '{"title":"第2005019条・金匮要略6  血痹虚劳","description":"<p>*、$q{附方《千金翼》}$f{炙甘草汤} $a{一云复脉汤。}治虚劳不足，汗出而闷，脉结悸，行动如常，不出百日，危急者，十一日死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2005019,"note":"","videoMemo":"","fangList":["炙甘草汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '*、$q{附方《千金翼》}$f{炙甘草汤} $a{一云复脉汤。}治虚劳不足，汗出而闷，脉结悸，行动如常，不出百日，危急者，十一日死。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'QMamiO7b1M5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kfE5YOAmBMO', 4, '{"title":"第2005020条・金匮要略6  血痹虚劳","description":"<p>*、$q{《肘后》}$f{獭肝散} 治冷劳，又主鬼疰一门相染。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2005020,"note":"","videoMemo":"","fangList":["獭肝散"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '*、$q{《肘后》}$f{獭肝散} 治冷劳，又主鬼疰一门相染。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'QMamiO7b1M5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0zDpQqlNf23', 4, '{"title":"第2006000条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>1、问曰：热在上焦者，因咳为肺痿。肺痿之病，从何得之？师曰：或从汗出，或从呕吐，或从消渴，小便利数，或从便难，又被快药下利，重亡津液，故得之。曰：寸口脉数，其人咳，口中反有浊唾涎沫者何？师曰：为肺痿之病。若口中辟辟燥，咳即胸中隐隐痛，脉反滑数，此为肺痈，咳唾脓血。脉数虚者为肺痿，数实者为肺痈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、问曰：热在上焦者，因咳为肺痿。肺痿之病，从何得之？师曰：或从汗出，或从呕吐，或从消渴，小便利数，或从便难，又被快药下利，重亡津液，故得之。曰：寸口脉数，其人咳，口中反有浊唾涎沫者何？师曰：为肺痿之病。若口中辟辟燥，咳即胸中隐隐痛，脉反滑数，此为肺痈，咳唾脓血。脉数虚者为肺痿，数实者为肺痈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YlnpXX4A3uM', 4, '{"title":"第2006001条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>2、问曰：病咳逆，脉之何以知此为肺痈？当有脓血，吐之则死，其脉何类？师曰：寸口脉微而数，微则为风，数则为热；微则汗出，数则恶寒。风中于卫，呼气不入；热过于荣，吸而不出。风伤皮毛，热伤血脉。风舍于肺，其人则咳，口干喘满，咽燥不渴，时唾浊沫，时时振寒。热之所过，血为之凝滞，蓄结痈脓，吐如米粥。始萌可救，脓成则死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、问曰：病咳逆，脉之何以知此为肺痈？当有脓血，吐之则死，其脉何类？师曰：寸口脉微而数，微则为风，数则为热；微则汗出，数则恶寒。风中于卫，呼气不入；热过于荣，吸而不出。风伤皮毛，热伤血脉。风舍于肺，其人则咳，口干喘满，咽燥不渴，时唾浊沫，时时振寒。热之所过，血为之凝滞，蓄结痈脓，吐如米粥。始萌可救，脓成则死。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kB8BVn6JXbJ', 4, '{"title":"第2006002条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>3、上气面浮肿，肩息，其脉浮大，不治，又加利尤甚。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、上气面浮肿，肩息，其脉浮大，不治，又加利尤甚。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mP3tqV5KyaO', 4, '{"title":"第2006003条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>4、上气喘而躁者，属肺胀，欲作风水，发汗则愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '4、上气喘而躁者，属肺胀，欲作风水，发汗则愈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pd9Bq2NmsyS', 4, '{"title":"第2006004条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>5、肺痿吐涎沫而不咳者，其人不渴，必遗尿，小便数。所以然者，以上虚不能制下故也。此为肺中冷，必眩，多涎唾，$f{甘草干姜汤}以温之。若服汤已渴者，属消渴。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006004,"note":"","videoMemo":"","fangList":["甘草干姜汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '5、肺痿吐涎沫而不咳者，其人不渴，必遗尿，小便数。所以然者，以上虚不能制下故也。此为肺中冷，必眩，多涎唾，$f{甘草干姜汤}以温之。若服汤已渴者，属消渴。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bX39BeeJYpj', 4, '{"title":"第2006005条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>6、咳而上气，喉中水鸡声，$f{射干麻黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006005,"note":"","videoMemo":"","fangList":["射干麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '6、咳而上气，喉中水鸡声，$f{射干麻黄汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
