INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZB0K3lrlWwk', 4, '{"title":"第2006011条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>12、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈，$f{桔梗汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006011,"note":"","videoMemo":"","fangList":["桔梗汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '12、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈，$f{桔梗汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oYBUL1YARXI', 4, '{"title":"第2006012条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>13、咳而上气，此为肺胀，其人喘，目如脱状，脉浮大者，$f{越婢加半夏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006012,"note":"","videoMemo":"","fangList":["越婢加半夏汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '13、咳而上气，此为肺胀，其人喘，目如脱状，脉浮大者，$f{越婢加半夏汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
