INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wBkbs93EaEa', 4, '{"title":"第2006019条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>*、$q{《千金》}$f{苇茎汤} 治咳有微热烦满，胸中甲错，是为肺痈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006019,"note":"","videoMemo":"","fangList":["苇茎汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '*、$q{《千金》}$f{苇茎汤} 治咳有微热烦满，胸中甲错，是为肺痈。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l0MdqN4TVSq', 4, '{"title":"第2006020条・金匮要略7  肺痿肺痈咳嗽上气","description":"<p>15、肺痈胸满胀，一身面目浮肿，鼻塞清涕出，不闻香臭酸辛，咳逆上气，喘鸣迫塞，$f{葶苈大枣泻肺汤}主之。$a{方见上，三日一剂，可至三四剂，此先服$f{小青龙汤}一剂乃进。$f{小青龙汤}方见咳嗽门中。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2006020,"note":"","videoMemo":"","fangList":["葶苈大枣泻肺汤","小青龙汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '15、肺痈胸满胀，一身面目浮肿，鼻塞清涕出，不闻香臭酸辛，咳逆上气，喘鸣迫塞，$f{葶苈大枣泻肺汤}主之。$a{方见上，三日一剂，可至三四剂，此先服$f{小青龙汤}一剂乃进。$f{小青龙汤}方见咳嗽门中。}', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8maybAiexa1');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GY7LPnTA7Zp', 4, '{"title":"第2007000条・金匮要略8  奔豚气病","description":"<p>1、师曰：病有奔豚，有吐脓，有惊怖，有火邪，此四部病，皆从惊发得之。师曰：奔豚病从少腹起，上冲咽喉，发作欲死，复还止，皆从惊恐得之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2007000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、师曰：病有奔豚，有吐脓，有惊怖，有火邪，此四部病，皆从惊发得之。师曰：奔豚病从少腹起，上冲咽喉，发作欲死，复还止，皆从惊恐得之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0hPa7ReM6m8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fUN1Q2Oe76q', 4, '{"title":"第2007001条・金匮要略8  奔豚气病","description":"<p>2、奔豚气上冲胸，腹痛，往来寒热，$f{奔豚汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2007001,"note":"","videoMemo":"","fangList":["奔豚汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2、奔豚气上冲胸，腹痛，往来寒热，$f{奔豚汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0hPa7ReM6m8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6EKEmSb3A8X', 4, '{"title":"第2007002条・金匮要略8  奔豚气病","description":"<p>3、发汗后，烧针令其汗，针处被寒，核起而赤者，必发奔豚，气从少腹上至心，灸其核上各一壮，与$f{桂枝加桂汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2007002,"note":"","videoMemo":"","fangList":["桂枝加桂汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '3、发汗后，烧针令其汗，针处被寒，核起而赤者，必发奔豚，气从少腹上至心，灸其核上各一壮，与$f{桂枝加桂汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0hPa7ReM6m8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gkfiKQ4XQRH', 4, '{"title":"第2007003条・金匮要略8  奔豚气病","description":"<p>4、发汗后，脐下悸者，欲作奔豚，$f{茯苓桂枝甘草大枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2007003,"note":"","videoMemo":"","fangList":["茯苓桂枝甘草大枣汤"],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '4、发汗后，脐下悸者，欲作奔豚，$f{茯苓桂枝甘草大枣汤}主之。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '0hPa7ReM6m8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tCghQ2q0hqZ', 4, '{"title":"第2008000条・金匮要略9  胸痹心痛短气","description":"<p>1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛。所以然者，责其极虚也。今阳虚知在上焦，所以胸痹、心痛者，以其阴弦故也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2008000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '2024-09-17T00:57:28.000Z', '1、师曰：夫脉当取太过不及，阳微阴弦，即胸痹而痛。所以然者，责其极虚也。今阳虚知在上焦，所以胸痹、心痛者，以其阴弦故也。', '2024-09-17T00:57:28.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'iY9O5nR3dpv');
