INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0pyPMmPALXL', 4, '{"title":"第2009008条・金匮要略10  腹满寒疝宿食","description":"<p>9、病腹满，发热十日，脉浮而数，饮食如故，$f{厚朴七物汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009008,"note":"","videoMemo":"","fangList":["厚朴七物汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '9、病腹满，发热十日，脉浮而数，饮食如故，$f{厚朴七物汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
