INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hvYlXVNo5JV', 4, '{"title":"第2009013条・金匮要略10  腹满寒疝宿食","description":"<p>14、心胸中大寒痛，呕不能饮食，腹中寒，上冲皮起，出见有头足，上下痛而不可触近，$f{大建中汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009013,"note":"","videoMemo":"","fangList":["大建中汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '14、心胸中大寒痛，呕不能饮食，腹中寒，上冲皮起，出见有头足，上下痛而不可触近，$f{大建中汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('snLTdwusqNY', 4, '{"title":"第2009014条・金匮要略10  腹满寒疝宿食","description":"<p>15、胁下偏痛，发热，其脉紧弦，此寒也，以温药下之，宜$f{大黄附子汤}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009014,"note":"","videoMemo":"","fangList":["大黄附子汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '15、胁下偏痛，发热，其脉紧弦，此寒也，以温药下之，宜$f{大黄附子汤}。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TQa0G26Q2aW', 4, '{"title":"第2009015条・金匮要略10  腹满寒疝宿食","description":"<p>16、寒气厥逆，$f{赤丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009015,"note":"","videoMemo":"","fangList":["赤丸"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '16、寒气厥逆，$f{赤丸}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y2lnJUqoB4P', 4, '{"title":"第2009016条・金匮要略10  腹满寒疝宿食","description":"<p>17、腹痛，脉弦而紧，弦则卫气不行，即恶寒，紧则不欲食，邪正相抟，即为寒疝。寒疝绕脐痛，若发则白汗出，手足厥冷，其脉沉弦$a{（一云沉紧，一云弦）}者，$f{大乌头煎}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009016,"note":"","videoMemo":"","fangList":["大乌头煎"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '17、腹痛，脉弦而紧，弦则卫气不行，即恶寒，紧则不欲食，邪正相抟，即为寒疝。寒疝绕脐痛，若发则白汗出，手足厥冷，其脉沉弦$a{（一云沉紧，一云弦）}者，$f{大乌头煎}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hv4XD0U6Wg8', 4, '{"title":"第2009017条・金匮要略10  腹满寒疝宿食","description":"<p>18、寒疝腹中痛，及胁痛里急者，$f{当归生姜羊肉汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009017,"note":"","videoMemo":"","fangList":["当归生姜羊肉汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '18、寒疝腹中痛，及胁痛里急者，$f{当归生姜羊肉汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lyGsGrroKcV', 4, '{"title":"第2009018条・金匮要略10  腹满寒疝宿食","description":"<p>19、寒疝腹中痛，逆冷，手足不仁，若身疼痛，灸、刺、诸药不能治，$a{抵当}$f{乌头桂枝汤}主之。    </p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009018,"note":"","videoMemo":"","fangList":["乌头桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '19、寒疝腹中痛，逆冷，手足不仁，若身疼痛，灸、刺、诸药不能治，$a{抵当}$f{乌头桂枝汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('whWrYklBpMe', 4, '{"title":"第2009019条・金匮要略10  腹满寒疝宿食","description":"<p>20、其脉数而紧乃弦，状如弓弦，按之不移。脉数弦者，当下其寒；脉紧大而迟者，必心下坚；脉大而紧者，阳中有阴，可下之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '20、其脉数而紧乃弦，状如弓弦，按之不移。脉数弦者，当下其寒；脉紧大而迟者，必心下坚；脉大而紧者，阳中有阴，可下之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
