INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vXo346HvPzF', 4, '{"title":"第2009021条・金匮要略10  腹满寒疝宿食","description":"<p>*、$q{《外台》}$f{柴胡桂枝汤} 治心腹卒中痛者。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2009021,"note":"","videoMemo":"","fangList":["柴胡桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '*、$q{《外台》}$f{柴胡桂枝汤} 治心腹卒中痛者。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '15pc4Qe55iZ');
