INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0P0d44z6Ogq', 4, '{"title":"第2010003条・金匮要略11  五脏风寒积聚","description":"<p>4、肝中风者，头目瞤，两胁痛，行常伛，令人嗜甘。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、肝中风者，头目瞤，两胁痛，行常伛，令人嗜甘。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8eUPzW6owVa', 4, '{"title":"第2010004条・金匮要略11  五脏风寒积聚","description":"<p>5、肝中寒者，两臂不举，舌本燥，喜太息，胸中痛，不得转侧，食则吐而汗出也。$a{《脉经》、《千金》云：时盗汗，咳，食已吐其汁。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、肝中寒者，两臂不举，舌本燥，喜太息，胸中痛，不得转侧，食则吐而汗出也。$a{《脉经》、《千金》云：时盗汗，咳，食已吐其汁。}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aUFQS8ISRum', 4, '{"title":"第2010005条・金匮要略11  五脏风寒积聚","description":"<p>6、肝死脏，浮之弱，按之如索不来，或曲如蛇行者，死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '6、肝死脏，浮之弱，按之如索不来，或曲如蛇行者，死。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uwEdLDPD5v3', 4, '{"title":"第2010006条・金匮要略11  五脏风寒积聚","description":"<p>7、肝着，其人常欲蹈其胸上，先未苦时，但欲饮热，$f{旋覆花汤}主之。$a{臣亿等校诸本旋覆花汤，皆同。同恐阙讹}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010006,"note":"","videoMemo":"","fangList":["旋覆花汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '7、肝着，其人常欲蹈其胸上，先未苦时，但欲饮热，$f{旋覆花汤}主之。$a{臣亿等校诸本旋覆花汤，皆同。同恐阙讹}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ob1lFpXkhps', 4, '{"title":"第2010007条・金匮要略11  五脏风寒积聚","description":"<p>8、心中风者，翕翕发热，不能起，心中饥，食即呕吐。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '8、心中风者，翕翕发热，不能起，心中饥，食即呕吐。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DTS2QTmyz30', 4, '{"title":"第2010008条・金匮要略11  五脏风寒积聚","description":"<p>9、心中寒者，其人苦病心如啖蒜状，剧者心痛彻背，背痛彻心，譬如蛊注。其脉浮者，自吐乃愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '9、心中寒者，其人苦病心如啖蒜状，剧者心痛彻背，背痛彻心，譬如蛊注。其脉浮者，自吐乃愈。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jFkYn4LPCVe', 4, '{"title":"第2010009条・金匮要略11  五脏风寒积聚","description":"<p>10、心伤者，其人劳倦，即头面赤而下重，心中痛而自烦，发热，当脐跳，其脉弦，此为心脏伤所致也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '10、心伤者，其人劳倦，即头面赤而下重，心中痛而自烦，发热，当脐跳，其脉弦，此为心脏伤所致也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vv65iA84bAb', 4, '{"title":"第2010010条・金匮要略11  五脏风寒积聚","description":"<p>11、心死脏，浮之实如麻豆，按之益躁疾者，死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '11、心死脏，浮之实如麻豆，按之益躁疾者，死。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RgMX9PsEmPS', 4, '{"title":"第2010011条・金匮要略11  五脏风寒积聚","description":"<p>12、邪哭使魂魄不安者，血气少也；血气少者属于心，心气虚者，其人则畏，合目欲眠，梦远行而精神离散，魂魄妄行。阴气衰者为癫，阳气衰者为狂。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '12、邪哭使魂魄不安者，血气少也；血气少者属于心，心气虚者，其人则畏，合目欲眠，梦远行而精神离散，魂魄妄行。阴气衰者为癫，阳气衰者为狂。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WVhmrEZkwwK', 4, '{"title":"第2010012条・金匮要略11  五脏风寒积聚","description":"<p>13、脾中风者，翕翕发热，形如醉人，腹中烦重，皮目瞤瞤而短气。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '13、脾中风者，翕翕发热，形如醉人，腹中烦重，皮目瞤瞤而短气。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e9g0jUoNblE', 4, '{"title":"第2010013条・金匮要略11  五脏风寒积聚","description":"<p>14、脾死脏，浮之大坚，按之如覆杯，洁洁状如摇者，死。$a{臣亿等详五脏各有中风中寒，今脾只载中风，肾中风中寒俱不载者，以古文简乱极多，去古既远，无他可以补缀也。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '14、脾死脏，浮之大坚，按之如覆杯，洁洁状如摇者，死。$a{臣亿等详五脏各有中风中寒，今脾只载中风，肾中风中寒俱不载者，以古文简乱极多，去古既远，无他可以补缀也。}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Pi2gfmvLDJd', 4, '{"title":"第2010014条・金匮要略11  五脏风寒积聚","description":"<p>15、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相抟，大便则坚，其脾为约，$f{麻子仁丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010014,"note":"","videoMemo":"","fangList":["麻子仁丸"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '15、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相抟，大便则坚，其脾为约，$f{麻子仁丸}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R7du3bKvaJ0', 4, '{"title":"第2010015条・金匮要略11  五脏风寒积聚","description":"<p>16、肾着之病，其人身体重，腰中冷，如坐水中，形如水状，反不渴，小便自利，饮食如故，病属下焦，身劳汗出，衣$a{一作表}里冷湿，久久得之，腰以下冷痛，腹重如带五千钱，$f{甘草干姜茯苓白术汤}主之。$a{。《千金》作肾着汤}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010015,"note":"","videoMemo":"","fangList":["甘草干姜茯苓白术汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '16、肾着之病，其人身体重，腰中冷，如坐水中，形如水状，反不渴，小便自利，饮食如故，病属下焦，身劳汗出，衣$a{一作表}里冷湿，久久得之，腰以下冷痛，腹重如带五千钱，$f{甘草干姜茯苓白术汤}主之。$a{。《千金》作肾着汤}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Pfs3LxFHaA8', 4, '{"title":"第2010016条・金匮要略11  五脏风寒积聚","description":"<p>17、肾死脏，浮之坚，按之乱如转丸，益下入尺中者，死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '17、肾死脏，浮之坚，按之乱如转丸，益下入尺中者，死。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EAWD1Wcoj0Z', 4, '{"title":"第2010017条・金匮要略11  五脏风寒积聚","description":"<p>18、问曰：三焦竭部，上焦竭善噫，何谓也？师曰：上焦受中焦气未和，不能消谷，故能噫耳。下焦竭，即遗溺失便，其气不和，不能自禁制，不须治，久则愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '18、问曰：三焦竭部，上焦竭善噫，何谓也？师曰：上焦受中焦气未和，不能消谷，故能噫耳。下焦竭，即遗溺失便，其气不和，不能自禁制，不须治，久则愈。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lK760cHJZeP', 4, '{"title":"第2010018条・金匮要略11  五脏风寒积聚","description":"<p>19、师曰：热在上焦者，因咳为肺痿；热在中焦者，则为坚；热在下焦者，则尿血，亦令淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便血；有热者，必痔。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '19、师曰：热在上焦者，因咳为肺痿；热在中焦者，则为坚；热在下焦者，则尿血，亦令淋秘不通。大肠有寒者，多鹜溏；有热者，便肠垢。小肠有寒者，其人下重便血；有热者，必痔。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fgRJLRYaTeS', 4, '{"title":"第2010019条・金匮要略11  五脏风寒积聚","description":"<p>20、问曰：病有积、有聚、有榖气，何谓也？师曰：积者，脏病也，终不移；聚者，府病也，发作有时，展转痛移，为可治；榖气者，胁下痛，按之则愈，复发为榖气。诸积大法：脉来细而附骨者，乃积也。寸口，积在胸中；微出寸口，积在喉中；关上，积在脐旁；上关上，积在心下；微下关，积在少腹。尺中，积在气冲；脉出左，积在左；脉出右，积在右；脉两出，积在中央。各以其部处之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2010019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '20、问曰：病有积、有聚、有榖气，何谓也？师曰：积者，脏病也，终不移；聚者，府病也，发作有时，展转痛移，为可治；榖气者，胁下痛，按之则愈，复发为榖气。诸积大法：脉来细而附骨者，乃积也。寸口，积在胸中；微出寸口，积在喉中；关上，积在脐旁；上关上，积在心下；微下关，积在少腹。尺中，积在气冲；脉出左，积在左；脉出右，积在右；脉两出，积在中央。各以其部处之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'YX4g5S2TBwb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MIaFcbShrz1', 4, '{"title":"第2011000条・金匮要略12  痰饮咳嗽","description":"<p>1、问曰：夫饮有四，何谓也？师曰：有痰饮，有悬饮，有溢饮，有支饮。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、问曰：夫饮有四，何谓也？师曰：有痰饮，有悬饮，有溢饮，有支饮。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KHFgml8ntPm', 4, '{"title":"第2011001条・金匮要略12  痰饮咳嗽","description":"<p>2、问曰：四饮何以为异？师曰：其人素盛今瘦，水走肠间，沥沥有声，谓之痰饮；饮后水流在胁下，咳唾引痛，谓之悬饮；饮水流行，归于四肢，当汗出而不汗出，身体疼重，谓之溢饮；咳逆倚息，短气不得卧，其形如肿，谓之支饮。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2、问曰：四饮何以为异？师曰：其人素盛今瘦，水走肠间，沥沥有声，谓之痰饮；饮后水流在胁下，咳唾引痛，谓之悬饮；饮水流行，归于四肢，当汗出而不汗出，身体疼重，谓之溢饮；咳逆倚息，短气不得卧，其形如肿，谓之支饮。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GKPllBlfdZm', 4, '{"title":"第2011002条・金匮要略12  痰饮咳嗽","description":"<p>3、水在心，心下坚筑，短气，恶水不欲饮。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '3、水在心，心下坚筑，短气，恶水不欲饮。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sHmM3fdTQN9', 4, '{"title":"第2011003条・金匮要略12  痰饮咳嗽","description":"<p>4、水在肺，吐涎沫，欲饮水。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、水在肺，吐涎沫，欲饮水。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RQ610WK9u7Y', 4, '{"title":"第2011004条・金匮要略12  痰饮咳嗽","description":"<p>5、水在脾，少气身重。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、水在脾，少气身重。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MDfivsqayzD', 4, '{"title":"第2011005条・金匮要略12  痰饮咳嗽","description":"<p>6、水在肝，胁下支满，嚏而痛。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '6、水在肝，胁下支满，嚏而痛。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
