INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fze7hsJhAEK', 4, '{"title":"第2011007条・金匮要略12  痰饮咳嗽","description":"<p>8、夫心下有留饮，其人背寒冷如手大。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '8、夫心下有留饮，其人背寒冷如手大。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8yScl3sAqFE', 4, '{"title":"第2011008条・金匮要略12  痰饮咳嗽","description":"<p>9、留饮者，胁下痛引缺盆，咳嗽则辄已。$a{一作转甚。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '9、留饮者，胁下痛引缺盆，咳嗽则辄已。$a{一作转甚。}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I1so7WMXvwU', 4, '{"title":"第2011009条・金匮要略12  痰饮咳嗽","description":"<p>10、胸中有留饮，其人短气而渴，四肢历节痛。脉沉者，有留饮。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '10、胸中有留饮，其人短气而渴，四肢历节痛。脉沉者，有留饮。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m7JofAE5RDY', 4, '{"title":"第2011010条・金匮要略12  痰饮咳嗽","description":"<p>11、膈上病痰，满喘咳吐，发则寒热，背痛腰疼，目泣自出，其人振振身瞤剧，必有伏饮。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '11、膈上病痰，满喘咳吐，发则寒热，背痛腰疼，目泣自出，其人振振身瞤剧，必有伏饮。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l2BxsStCJm2', 4, '{"title":"第2011011条・金匮要略12  痰饮咳嗽","description":"<p>12、夫病人饮水多，必暴喘满。凡食少饮多，水停心下，甚者则悸，微者短气。脉双弦者，寒也，皆大下后善虚；脉偏弦者，饮也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '12、夫病人饮水多，必暴喘满。凡食少饮多，水停心下，甚者则悸，微者短气。脉双弦者，寒也，皆大下后善虚；脉偏弦者，饮也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P4HkM841Luv', 4, '{"title":"第2011012条・金匮要略12  痰饮咳嗽","description":"<p>13、肺饮不弦，但苦喘短气。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '13、肺饮不弦，但苦喘短气。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
