INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E23neZeFTf5', 4, '{"title":"第2011023条・金匮要略12  痰饮咳嗽","description":"<p>24、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈，$f{木防己汤}主之。虚者即愈，实者三日复发。复与不愈者，宜$f{木防己去石膏加茯苓芒硝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011023,"note":"","videoMemo":"","fangList":["木防己汤","木防己去石膏加茯苓芒硝汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '24、膈间支饮，其人喘满，心下痞坚，面色黧黑，其脉沉紧，得之数十日，医吐下之不愈，$f{木防己汤}主之。虚者即愈，实者三日复发。复与不愈者，宜$f{木防己去石膏加茯苓芒硝汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
