INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hhvNtFkLVlL', 4, '{"title":"第2011027条・金匮要略12  痰饮咳嗽","description":"<p>28、呕家本渴，渴者为欲解，今反不渴，$a{$q{《千金》}作呕家不渴，渴者为欲解，本渴今反不渴。}心下有支饮故也，$f{小半夏汤}主之。$a{$q{《千金》}云：$f{小半夏加茯苓汤}。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011027,"note":"","videoMemo":"","fangList":["小半夏汤","小半夏加茯苓汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '28、呕家本渴，渴者为欲解，今反不渴，$a{$q{《千金》}作呕家不渴，渴者为欲解，本渴今反不渴。}心下有支饮故也，$f{小半夏汤}主之。$a{$q{《千金》}云：$f{小半夏加茯苓汤}。}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g2u3w0aITDl', 4, '{"title":"第2011028条・金匮要略12  痰饮咳嗽","description":"<p>29、腹满，口舌干燥，此肠间有水气，$f{己椒苈黄丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011028,"note":"","videoMemo":"","fangList":["己椒苈黄丸"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '29、腹满，口舌干燥，此肠间有水气，$f{己椒苈黄丸}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
