INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cBo9ggeJQUE', 4, '{"title":"第2011030条・金匮要略12  痰饮咳嗽","description":"<p>31、假令瘦人脐下有悸，吐涎沫而癫眩，此水也，$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011030,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '31、假令瘦人脐下有悸，吐涎沫而癫眩，此水也，$f{五苓散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
