INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zb3hClbDnxY', 4, '{"title":"第2011032条・金匮要略12  痰饮咳嗽","description":"<p>32、咳家其脉弦，为有水，$f{十枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011032,"note":"","videoMemo":"","fangList":["十枣汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '32、咳家其脉弦，为有水，$f{十枣汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('orGP2sc0a7K', 4, '{"title":"第2011033条・金匮要略12  痰饮咳嗽","description":"<p>33、夫有支饮家，咳烦，胸中痛者，不卒死，至一百日或一岁，宜$f{十枣汤}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011033,"note":"","videoMemo":"","fangList":["十枣汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '33、夫有支饮家，咳烦，胸中痛者，不卒死，至一百日或一岁，宜$f{十枣汤}。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XUURkzyzQ01', 4, '{"title":"第2011034条・金匮要略12  痰饮咳嗽","description":"<p>34、久咳数岁，其脉弱者可治，实大数者死；其脉虚者必苦冒，其人本有支饮在胸中故也，治属饮家。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011034,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '34、久咳数岁，其脉弱者可治，实大数者死；其脉虚者必苦冒，其人本有支饮在胸中故也，治属饮家。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MK1ltV54qKL', 4, '{"title":"第2011035条・金匮要略12  痰饮咳嗽","description":"<p>35、咳逆倚息不得卧，$f{小青龙汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011035,"note":"","videoMemo":"","fangList":["小青龙汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '35、咳逆倚息不得卧，$f{小青龙汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sRNyL3CDakx', 4, '{"title":"第2011036条・金匮要略12  痰饮咳嗽","description":"<p>36、$f{青龙汤}下已，多唾口燥，寸脉沉，尺脉微，手足厥逆，气从小腹上冲胸咽，手足痹，其面翕热如醉状，因复下流阴股，小便难，时复冒者，与$f{桂苓五味甘草汤}，治其气冲。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011036,"note":"","videoMemo":"","fangList":["青龙汤","桂苓五味甘草汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '36、$f{青龙汤}下已，多唾口燥，寸脉沉，尺脉微，手足厥逆，气从小腹上冲胸咽，手足痹，其面翕热如醉状，因复下流阴股，小便难，时复冒者，与$f{桂苓五味甘草汤}，治其气冲。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EV1rqnLmF9t', 4, '{"title":"第2011037条・金匮要略12  痰饮咳嗽","description":"<p>37、冲气即低，而反更咳，胸满者，用$f{桂苓五味甘草汤}去桂加$u{干姜}、$u{细辛}，以治其咳满。$a{即$f{苓甘五味姜辛汤}}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011037,"note":"","videoMemo":"","fangList":["桂苓五味甘草汤","苓甘五味姜辛汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '37、冲气即低，而反更咳，胸满者，用$f{桂苓五味甘草汤}去桂加$u{干姜}、$u{细辛}，以治其咳满。$a{即$f{苓甘五味姜辛汤}}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nnJWEsbU5d8', 4, '{"title":"第2011038条・金匮要略12  痰饮咳嗽","description":"<p>38、咳满即止，而更复渴，冲气复发者，以$u{细辛}、$u{干姜}为热药也。服之当遂渴，而渴反止者，为支饮也。支饮者，法当冒，冒者必呕，呕者复内$u{半夏}，以去其水。$a{即$f{桂苓五味甘草去桂加干姜细辛半夏汤}}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011038,"note":"","videoMemo":"","fangList":["桂苓五味甘草去桂加干姜细辛半夏汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '38、咳满即止，而更复渴，冲气复发者，以$u{细辛}、$u{干姜}为热药也。服之当遂渴，而渴反止者，为支饮也。支饮者，法当冒，冒者必呕，呕者复内$u{半夏}，以去其水。$a{即$f{桂苓五味甘草去桂加干姜细辛半夏汤}}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('70SL7k6p6HT', 4, '{"title":"第2011039条・金匮要略12  痰饮咳嗽","description":"<p>39、水去呕止，其人形肿者，加$u{杏仁}主之。其证应内$u{麻黄}，以其人遂痹，故不内之；若逆而内之者，必厥。所以然者，以其人血虚，$u{麻黄}发其阳故也。$a{即$f{苓甘五味加姜辛半夏杏仁汤}}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011039,"note":"","videoMemo":"","fangList":["苓甘五味加姜辛半夏杏仁汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '39、水去呕止，其人形肿者，加$u{杏仁}主之。其证应内$u{麻黄}，以其人遂痹，故不内之；若逆而内之者，必厥。所以然者，以其人血虚，$u{麻黄}发其阳故也。$a{即$f{苓甘五味加姜辛半夏杏仁汤}}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vnY4WzYaiJZ', 4, '{"title":"第2011040条・金匮要略12  痰饮咳嗽","description":"<p>40、若面热如醉，此为胃热上冲，熏其面，加$u{大黄}以利之。$a{即$f{苓甘五味加姜辛半杏大黄汤}}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011040,"note":"","videoMemo":"","fangList":["苓甘五味加姜辛半杏大黄汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '40、若面热如醉，此为胃热上冲，熏其面，加$u{大黄}以利之。$a{即$f{苓甘五味加姜辛半杏大黄汤}}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A2yk8wbXZPf', 4, '{"title":"第2011041条・金匮要略12  痰饮咳嗽","description":"<p>41、先渴后呕，为水停心下，此属饮家，$f{小半夏加茯苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2011041,"note":"","videoMemo":"","fangList":["小半夏加茯苓汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '41、先渴后呕，为水停心下，此属饮家，$f{小半夏加茯苓汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '3N8wyjAR0z6');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7k0P12eh1PN', 4, '{"title":"第2012000条・金匮要略13  消渴小便不利淋病","description":"<p>1、厥阴之为病，消渴，气上冲心，心中疼热，饥而不欲食，食即吐，下之不肯止。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、厥阴之为病，消渴，气上冲心，心中疼热，饥而不欲食，食即吐，下之不肯止。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BboIDW9guL8', 4, '{"title":"第2012001条・金匮要略13  消渴小便不利淋病","description":"<p>2、寸口脉浮而迟，浮即为虚，迟即为劳，虚则卫气不足，劳则荣$a{一云营}气竭。趺阳脉浮而数，浮即为气，数即消谷而大坚$a{一作紧}，气盛则溲数，溲数即坚，坚数相抟，即为消渴。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2、寸口脉浮而迟，浮即为虚，迟即为劳，虚则卫气不足，劳则荣$a{一云营}气竭。趺阳脉浮而数，浮即为气，数即消谷而大坚$a{一作紧}，气盛则溲数，溲数即坚，坚数相抟，即为消渴。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c3Kh7MEUUIM', 4, '{"title":"第2012002条・金匮要略13  消渴小便不利淋病","description":"<p>3、男子消渴，小便反多，以饮一斗，小便一斗，$f{肾气丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012002,"note":"","videoMemo":"","fangList":["肾气丸"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '3、男子消渴，小便反多，以饮一斗，小便一斗，$f{肾气丸}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ja3Qi3TQRF4', 4, '{"title":"第2012003条・金匮要略13  消渴小便不利淋病","description":"<p>4、脉浮，小便不利，微热消渴者，宜利小便、发汗，$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012003,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、脉浮，小便不利，微热消渴者，宜利小便、发汗，$f{五苓散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZMUCdNpxqMC', 4, '{"title":"第2012004条・金匮要略13  消渴小便不利淋病","description":"<p>5、渴欲饮水，水入则吐者，名曰水逆，$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012004,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、渴欲饮水，水入则吐者，名曰水逆，$f{五苓散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('guonQ15MaMl', 4, '{"title":"第2012005条・金匮要略13  消渴小便不利淋病","description":"<p>6、渴欲饮水不止者，$f{文蛤散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012005,"note":"","videoMemo":"","fangList":["文蛤散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '6、渴欲饮水不止者，$f{文蛤散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OYSiv4R6M1C', 4, '{"title":"第2012006条・金匮要略13  消渴小便不利淋病","description":"<p>7、淋之为病，小便如粟状，小腹弦急，痛引脐中。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '7、淋之为病，小便如粟状，小腹弦急，痛引脐中。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
