INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jfGExzc8vHv', 4, '{"title":"第2012008条・金匮要略13  消渴小便不利淋病","description":"<p>9、淋家不可发汗，发汗则必便血。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '9、淋家不可发汗，发汗则必便血。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H7BVWm8QrCH', 4, '{"title":"第2012009条・金匮要略13  消渴小便不利淋病","description":"<p>10、小便不利者，有水气，其人若渴，$f{栝楼瞿麦丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012009,"note":"","videoMemo":"","fangList":["栝楼瞿麦丸"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '10、小便不利者，有水气，其人若渴，$f{栝楼瞿麦丸}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ISmm8xsmj8t', 4, '{"title":"第2012010条・金匮要略13  消渴小便不利淋病","description":"<p>11、小便不利，$f{蒲灰散}主之，$f{滑石白鱼散}、$f{茯苓戎盐汤}并主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012010,"note":"","videoMemo":"","fangList":["蒲灰散","滑石白鱼散","茯苓戎盐汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '11、小便不利，$f{蒲灰散}主之，$f{滑石白鱼散}、$f{茯苓戎盐汤}并主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5ycXb2cJExB', 4, '{"title":"第2012011条・金匮要略13  消渴小便不利淋病","description":"<p>12、渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012011,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '12、渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ivkkb5IUWvV', 4, '{"title":"第2012012条・金匮要略13  消渴小便不利淋病","description":"<p>13、脉浮发热，渴欲饮水，小便不利者，$f{猪苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2012012,"note":"","videoMemo":"","fangList":["猪苓汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '13、脉浮发热，渴欲饮水，小便不利者，$f{猪苓汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'IpNd7TUi1u4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LydmON0yNeC', 4, '{"title":"第2013000条・金匮要略14  水气病","description":"<p>1、师曰：病有风水，有皮水，有正水，有石水，有黄汗。风水，其脉自浮，外证骨节疼痛，恶风；皮水，其脉亦浮，外证胕肿，按之没指，不恶风，其腹如鼓，不渴，当发其汗；正水，其脉沉迟，外证自喘；石水，其脉自沉，外证腹满不喘；黄汗，其脉沉迟，身发热，胸满，四肢头面肿，久不愈，必致痈脓。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、师曰：病有风水，有皮水，有正水，有石水，有黄汗。风水，其脉自浮，外证骨节疼痛，恶风；皮水，其脉亦浮，外证胕肿，按之没指，不恶风，其腹如鼓，不渴，当发其汗；正水，其脉沉迟，外证自喘；石水，其脉自沉，外证腹满不喘；黄汗，其脉沉迟，身发热，胸满，四肢头面肿，久不愈，必致痈脓。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Ez5zqrvKdo', 4, '{"title":"第2013001条・金匮要略14  水气病","description":"<p>2、脉浮而洪，浮则为风，洪则为气，风气相抟，风强则为隐疹，身体为痒，痒为泄风，久为痂癞；气强则为水，难以俯仰。风气相击，身体洪肿，汗出乃愈。恶风则虚，此为风水；不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2、脉浮而洪，浮则为风，洪则为气，风气相抟，风强则为隐疹，身体为痒，痒为泄风，久为痂癞；气强则为水，难以俯仰。风气相击，身体洪肿，汗出乃愈。恶风则虚，此为风水；不恶风者，小便通利，上焦有寒，其口多涎，此为黄汗。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KLdgFmV2cHV', 4, '{"title":"第2013002条・金匮要略14  水气病","description":"<p>3、寸口脉沉滑者，中有水气，面目肿大，有热，名曰风水。视人之目窠上微拥，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，风水。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '3、寸口脉沉滑者，中有水气，面目肿大，有热，名曰风水。视人之目窠上微拥，如蚕新卧起状，其颈脉动，时时咳，按其手足上，陷而不起者，风水。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BTk8jhD8U5T', 4, '{"title":"第2013003条・金匮要略14  水气病","description":"<p>4、太阳病，脉浮而紧，法当骨节疼痛，反不疼，身体反重而酸，其人不渴，汗出即愈，此为风水。恶寒者，此为极虚，发汗得之。渴而不恶寒者，此为皮水。身肿而冷，状如周痹，胸中窒，不能食，反聚痛，暮躁不得眠，此为黄汗，痛在骨节。咳而喘，不渴者，此为脾胀，其状如肿，发汗即愈。然诸病此者，渴而下利，小便数者，皆不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、太阳病，脉浮而紧，法当骨节疼痛，反不疼，身体反重而酸，其人不渴，汗出即愈，此为风水。恶寒者，此为极虚，发汗得之。渴而不恶寒者，此为皮水。身肿而冷，状如周痹，胸中窒，不能食，反聚痛，暮躁不得眠，此为黄汗，痛在骨节。咳而喘，不渴者，此为脾胀，其状如肿，发汗即愈。然诸病此者，渴而下利，小便数者，皆不可发汗。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1lGih2AzJbF', 4, '{"title":"第2013004条・金匮要略14  水气病","description":"<p>5、里水者，一身面目黄肿，其脉沉，小便不利，故令病水。假如小便自利，此亡津液，故令渴也。$f{越婢加术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013004,"note":"","videoMemo":"","fangList":["越婢加术汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、里水者，一身面目黄肿，其脉沉，小便不利，故令病水。假如小便自利，此亡津液，故令渴也。$f{越婢加术汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O6f7CEhP3mQ', 4, '{"title":"第2013005条・金匮要略14  水气病","description":"<p>6、趺阳脉当伏，今反紧，本自有寒，疝瘕，腹中痛，医反下之，下之即胸满短气。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '6、趺阳脉当伏，今反紧，本自有寒，疝瘕，腹中痛，医反下之，下之即胸满短气。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f0AXgLOXj8b', 4, '{"title":"第2013006条・金匮要略14  水气病","description":"<p>7、趺阳脉当伏，今反数，本自有热，消谷，小便数，今反不利，此欲作水。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '7、趺阳脉当伏，今反数，本自有热，消谷，小便数，今反不利，此欲作水。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MHhnFDfdsYy', 4, '{"title":"第2013007条・金匮要略14  水气病","description":"<p>8、寸口脉浮而迟，浮脉则热，迟脉则潜，热潜相抟，名目沉。趺阳脉浮而数，浮脉即热，数脉即止，热止相抟，名曰伏。沉伏相抟，名曰水。沉则脉络虚，伏则小便难，虚难相抟，水走皮肤，即为水矣。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '8、寸口脉浮而迟，浮脉则热，迟脉则潜，热潜相抟，名目沉。趺阳脉浮而数，浮脉即热，数脉即止，热止相抟，名曰伏。沉伏相抟，名曰水。沉则脉络虚，伏则小便难，虚难相抟，水走皮肤，即为水矣。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5sTEs2QmYae', 4, '{"title":"第2013008条・金匮要略14  水气病","description":"<p>9、寸口脉弦而紧，弦则卫气不行，即恶寒，水不沾流，走于肠间。少阴脉紧而沉，紧则为痛，沉则为水，小便即难。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '9、寸口脉弦而紧，弦则卫气不行，即恶寒，水不沾流，走于肠间。少阴脉紧而沉，紧则为痛，沉则为水，小便即难。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D7eAiXPY4oi', 4, '{"title":"第2013009条・金匮要略14  水气病","description":"<p>10、脉得诸沉，当责有水，身体肿重。水病脉出者死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '10、脉得诸沉，当责有水，身体肿重。水病脉出者死。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oc9bD1gpqG6', 4, '{"title":"第2013010条・金匮要略14  水气病","description":"<p>11、夫水病人，目下有卧蚕，面目鲜泽，脉伏，其人消渴。病水腹大，小便不利，其脉沉绝者，有水，可下之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '11、夫水病人，目下有卧蚕，面目鲜泽，脉伏，其人消渴。病水腹大，小便不利，其脉沉绝者，有水，可下之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GkJTejq6nMS', 4, '{"title":"第2013011条・金匮要略14  水气病","description":"<p>12、问曰：病下利后，渴饮水，小便不利，腹满因肿者，何也？答曰：此法当病水，若小便自利及汗出者，自当愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '12、问曰：病下利后，渴饮水，小便不利，腹满因肿者，何也？答曰：此法当病水，若小便自利及汗出者，自当愈。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EOuGP1tC5PQ', 4, '{"title":"第2013012条・金匮要略14  水气病","description":"<p>13、心水者，其身重而少气，不得卧，烦而躁，其人阴肿。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '13、心水者，其身重而少气，不得卧，烦而躁，其人阴肿。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1kuC6rxZO8L', 4, '{"title":"第2013013条・金匮要略14  水气病","description":"<p>14、肝水者，其腹大，不能自转侧，胁下腹痛，时时津液微生，小便续通。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '14、肝水者，其腹大，不能自转侧，胁下腹痛，时时津液微生，小便续通。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hw50W3k6bEF', 4, '{"title":"第2013014条・金匮要略14  水气病","description":"<p>15、肺水者，其身肿，小便难，时时鸭溏。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '15、肺水者，其身肿，小便难，时时鸭溏。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Jsl0TKdnce', 4, '{"title":"第2013015条・金匮要略14  水气病","description":"<p>16、脾水者，其腹大，四肢苦重，津液不生，但苦少气，小便难。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '16、脾水者，其腹大，四肢苦重，津液不生，但苦少气，小便难。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4C2b8LMzWp2', 4, '{"title":"第2013016条・金匮要略14  水气病","description":"<p>17、肾水者，其腹大，脐肿腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '17、肾水者，其腹大，脐肿腰痛，不得溺，阴下湿如牛鼻上汗，其足逆冷，面反瘦。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A7JcKsDpWgi', 4, '{"title":"第2013017条・金匮要略14  水气病","description":"<p>18、师曰：诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '18、师曰：诸有水者，腰以下肿，当利小便；腰以上肿，当发汗乃愈。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l9mcxdPdAFs', 4, '{"title":"第2013018条・金匮要略14  水气病","description":"<p>19、师曰：寸口脉沉而迟，沉则为水，迟则为寒，寒水相抟。趺阳脉伏，水谷不化，脾气衰则鹜溏，胃气衰则身肿。少阳脉卑，少阴脉细，男子则小便不利，妇人则经水不通。经为血，血不利则为水，名曰血分。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013018,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '19、师曰：寸口脉沉而迟，沉则为水，迟则为寒，寒水相抟。趺阳脉伏，水谷不化，脾气衰则鹜溏，胃气衰则身肿。少阳脉卑，少阴脉细，男子则小便不利，妇人则经水不通。经为血，血不利则为水，名曰血分。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yYp7lhSXI9C', 4, '{"title":"第2013019条・金匮要略14  水气病","description":"<p>20、问曰：病有血分、水分，何也？师曰：经水前断，后病水，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治。何以故？去水，其经自下。$a{此条原本缺，据《脉经》及其他注本补入。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013019,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '20、问曰：病有血分、水分，何也？师曰：经水前断，后病水，名曰血分，此病难治；先病水，后经水断，名曰水分，此病易治。何以故？去水，其经自下。$a{此条原本缺，据《脉经》及其他注本补入。}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D3DY6P26q1i', 4, '{"title":"第2013020条・金匮要略14  水气病","description":"<p>21、问曰：病者苦水，面目身体四肢皆肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽，状如炙肉，当微咳喘。审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相抟，结在关元，始时当微，年盛不觉。阳衰之后，营卫相干，阳损阴盛，结寒微动，肾气上冲，喉咽塞噎，胁下急痛。医以为留饮而大下之，气击不去，其病不除。后重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿。又以葶苈丸下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则浮咳喘逆。当先攻击冲气，令止，乃治咳，咳止，其喘自差。先治新病，病当在后。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013020,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '21、问曰：病者苦水，面目身体四肢皆肿，小便不利，脉之，不言水，反言胸中痛，气上冲咽，状如炙肉，当微咳喘。审如师言，其脉何类？师曰：寸口脉沉而紧，沉为水，紧为寒，沉紧相抟，结在关元，始时当微，年盛不觉。阳衰之后，营卫相干，阳损阴盛，结寒微动，肾气上冲，喉咽塞噎，胁下急痛。医以为留饮而大下之，气击不去，其病不除。后重吐之，胃家虚烦，咽燥欲饮水，小便不利，水谷不化，面目手足浮肿。又以葶苈丸下水，当时如小差，食饮过度，肿复如前，胸胁苦痛，象若奔豚，其水扬溢，则浮咳喘逆。当先攻击冲气，令止，乃治咳，咳止，其喘自差。先治新病，病当在后。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AxjbAnXseG1', 4, '{"title":"第2013021条・金匮要略14  水气病","description":"<p>22、风水，脉浮身重，汗出恶风者，$f{防己黄芪汤}主之。腹痛加$u{芍药}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013021,"note":"","videoMemo":"","fangList":["防己黄芪汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '22、风水，脉浮身重，汗出恶风者，$f{防己黄芪汤}主之。腹痛加$u{芍药}。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3XPUXHBlY41', 4, '{"title":"第2013022条・金匮要略14  水气病","description":"<p>23、风水恶风，一身悉肿，脉浮不渴，续自汗出，无大热，$f{越婢汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013022,"note":"","videoMemo":"","fangList":["越婢汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '23、风水恶风，一身悉肿，脉浮不渴，续自汗出，无大热，$f{越婢汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RVaV0kiRcxr', 4, '{"title":"第2013023条・金匮要略14  水气病","description":"<p>24、皮水为病，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防己茯苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013023,"note":"","videoMemo":"","fangList":["防己茯苓汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '24、皮水为病，四肢肿，水气在皮肤中，四肢聂聂动者，$f{防己茯苓汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LRxbsYBLkGp', 4, '{"title":"第2013024条・金匮要略14  水气病","description":"<p>25、里水，$f{越婢加术汤}主之，$f{甘草麻黄汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013024,"note":"","videoMemo":"","fangList":["越婢加术汤","甘草麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '25、里水，$f{越婢加术汤}主之，$f{甘草麻黄汤}亦主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gkolhqgKrmo', 4, '{"title":"第2013025条・金匮要略14  水气病","description":"<p>26、水之为病，其脉沉小，属少阴；浮者为风；无水，虚胀者，为气。水，发其汗即已。脉沉者，宜$f{麻黄附子汤}；浮者，宜$f{杏子汤}。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013025,"note":"","videoMemo":"","fangList":["麻黄附子汤","杏子汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '26、水之为病，其脉沉小，属少阴；浮者为风；无水，虚胀者，为气。水，发其汗即已。脉沉者，宜$f{麻黄附子汤}；浮者，宜$f{杏子汤}。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q9sNZVVQHiY', 4, '{"title":"第2013026条・金匮要略14  水气病","description":"<p>27、厥而皮水者，$f{蒲灰散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013026,"note":"","videoMemo":"","fangList":["蒲灰散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '27、厥而皮水者，$f{蒲灰散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D99hFjyk592', 4, '{"title":"第2013027条・金匮要略14  水气病","description":"<p>28、问曰：黄汗之为病，身体肿，$a{一作重}，发热汗出而渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，何从得之？师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝苦酒汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013027,"note":"","videoMemo":"","fangList":["黄芪芍药桂枝苦酒汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '28、问曰：黄汗之为病，身体肿，$a{一作重}，发热汗出而渴，状如风水，汗沾衣，色正黄如柏汁，脉自沉，何从得之？师曰：以汗出入水中浴，水从汗孔入得之，宜$f{黄芪芍药桂枝苦酒汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k6ntCiX7Rpg', 4, '{"title":"第2013028条・金匮要略14  水气病","description":"<p>29、黄汗之病，两胫自冷。假令发热，此属历节。食已汗出，又身常暮盗汗出者，此劳气也。若汗出已，反发热者，久久其身必甲错；发热不止者，必生恶疮。若身重，汗出已辄轻者，久久必身瞤。瞤即胸中痛，又从腰以上必汗出，下无汗，腰髋弛痛，如有物在皮中状，剧者不能食，身疼重，烦躁，小便不利，此为黄汗。$f{桂枝加黄芪汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013028,"note":"","videoMemo":"","fangList":["桂枝加黄芪汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '29、黄汗之病，两胫自冷。假令发热，此属历节。食已汗出，又身常暮盗汗出者，此劳气也。若汗出已，反发热者，久久其身必甲错；发热不止者，必生恶疮。若身重，汗出已辄轻者，久久必身瞤。瞤即胸中痛，又从腰以上必汗出，下无汗，腰髋弛痛，如有物在皮中状，剧者不能食，身疼重，烦躁，小便不利，此为黄汗。$f{桂枝加黄芪汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XLU9YygOiu9', 4, '{"title":"第2013029条・金匮要略14  水气病","description":"<p>30、师曰：寸口脉迟而涩，迟则为寒，涩为血不足。趺阳脉微而迟，微则为气，迟则为寒。寒气不足，则手足逆冷；手足逆冷，则荣卫不利；荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼；阳前通则恶寒，阴前通则痹不仁；阴阳相得，其气乃行，大气一转，其气乃散；实则失气，虚则遗尿，名曰气分。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '30、师曰：寸口脉迟而涩，迟则为寒，涩为血不足。趺阳脉微而迟，微则为气，迟则为寒。寒气不足，则手足逆冷；手足逆冷，则荣卫不利；荣卫不利，则腹满肠鸣相逐，气转膀胱，荣卫俱劳。阳气不通即身冷，阴气不通即骨疼；阳前通则恶寒，阴前通则痹不仁；阴阳相得，其气乃行，大气一转，其气乃散；实则失气，虚则遗尿，名曰气分。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KV88LP0Eod2', 4, '{"title":"第2013030条・金匮要略14  水气病","description":"<p>31、气分，心下坚，大如盘，边如旋杯，水饮所作，$f{桂枝去芍药加麻黄细辛附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013030,"note":"","videoMemo":"","fangList":["桂枝去芍药加麻黄细辛附子汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '31、气分，心下坚，大如盘，边如旋杯，水饮所作，$f{桂枝去芍药加麻黄细辛附子汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
